// Curatorial opening essays per category (shown at the top of a category page).
// Categories without an entry fall back to their short blurb.
export const CATEGORY_INTRO: Record<string, Localized> = {
  history: {
    ms: 'Sejarah Malaysia ialah kisah sebuah persimpangan dunia. Dari kerajaan Hindu-Buddha purba di Lembah Bujang, ke kegemilangan Kesultanan Melaka, zaman penjajahan Portugis, Belanda dan British, pendudukan Jepun, perjuangan kemerdekaan, hinggalah pembentukan Malaysia — setiap zaman meninggalkan lapisannya pada negara hari ini. Terokai sejarah negara mengikut era.',
    en: "Malaysia's history is the story of a global crossroads. From the ancient Hindu-Buddhist kingdoms of the Bujang Valley, through the golden age of the Malacca Sultanate, the Portuguese, Dutch and British colonial eras, the Japanese occupation, the struggle for independence, and the formation of Malaysia — each age left its layer on the nation of today. Explore the country's history by era.",
    zh: '马来西亚的历史是一个世界十字路口的故事。从布央谷的古代印度教-佛教王国，到马六甲苏丹王朝的黄金时代，历经葡萄牙、荷兰与英国殖民时期、日据时期、独立斗争，直到马来西亚的成立——每个时代都为今日的国家留下了印记。按时代探索这个国家的历史。',
    ta: 'மலேசியாவின் வரலாறு ஒரு உலகச் சந்திப்பு முனையின் கதை. Bujang பள்ளத்தாக்கின் பண்டைய இந்து-பௌத்த அரசுகளிலிருந்து, மலாக்கா சுல்தானகத்தின் பொற்காலம், போர்த்துகீசிய, டச்சு மற்றும் பிரிட்டிஷ் காலனித்துவ காலங்கள், ஜப்பானியர் ஆக்கிரமிப்பு, சுதந்திரப் போராட்டம், மலேசியாவின் உருவாக்கம் வரை — ஒவ்வொரு காலகட்டமும் இன்றைய நாட்டின் மீது தன் அடையாளத்தை விட்டுச் சென்றுள்ளது. நாட்டின் வரலாற்றை காலகட்டம் வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシアの歴史は、世界の十字路の物語です。ブジャン渓谷の古代ヒンドゥー・仏教王国から、マラッカ王国の黄金時代、ポルトガル・オランダ・イギリスの植民地時代、日本占領、独立への闘い、そしてマレーシアの成立まで——それぞれの時代が今日の国に層を重ねてきました。国の歴史を時代別にたどってみましょう。',
    ko: '말레이시아(Malaysia)의 역사는 세계의 교차로에 관한 이야기입니다. 부장 계곡(Bujang Valley)의 고대 힌두·불교 왕국에서 시작하여, 말라카 술탄국(Malacca Sultanate)의 황금기, 포르투갈·네덜란드·영국의 식민 시대, 일본 점령기, 독립 투쟁, 그리고 말레이시아의 성립에 이르기까지 — 각 시대가 오늘날의 국가 위에 저마다의 층을 남겼습니다. 시대별로 이 나라의 역사를 탐색해 보십시오.',
    th: 'ประวัติศาสตร์ของมาเลเซีย (Malaysia) คือเรื่องราวของจุดบรรจบแห่งโลก จากอาณาจักรฮินดู-พุทธโบราณในหุบเขาบูจัง (Bujang Valley) ผ่านยุคทองของรัฐสุลต่านมะละกา (Malacca Sultanate) ยุคอาณานิคมโปรตุเกส ดัตช์ และอังกฤษ การยึดครองของญี่ปุ่น การต่อสู้เพื่อเอกราช จนถึงการก่อตั้งประเทศมาเลเซีย — แต่ละยุคสมัยได้ทิ้งชั้นของตนไว้บนชาติในปัจจุบัน สำรวจประวัติศาสตร์ของประเทศตามยุคสมัย',
    vi: 'Lịch sử Malaysia là câu chuyện về một ngã tư của thế giới. Từ các vương quốc Hindu-Phật giáo cổ đại ở Thung lũng Bujang (Bujang Valley), qua thời hoàng kim của Vương quốc Hồi giáo Malacca (Malacca Sultanate), các thời kỳ thuộc địa Bồ Đào Nha, Hà Lan và Anh, thời kỳ Nhật Bản chiếm đóng, cuộc đấu tranh giành độc lập, cho đến sự hình thành của Malaysia — mỗi thời đại đều để lại tầng lớp của mình trên đất nước ngày nay. Khám phá lịch sử đất nước theo từng thời đại.',
    id: 'Sejarah Malaysia adalah kisah sebuah persimpangan dunia. Dari kerajaan Hindu-Buddha kuno di Lembah Bujang, hingga kejayaan Kesultanan Melaka, era penjajahan Portugis, Belanda, dan Inggris, pendudukan Jepang, perjuangan kemerdekaan, hingga pembentukan Malaysia — setiap era meninggalkan lapisannya pada negara saat ini. Jelajahi sejarah negara ini berdasarkan era.',
    ar: 'تاريخ ماليزيا هو قصة مُفترَق طرق عالمي. من الممالك الهندوسية البوذية القديمة في وادي بوجانغ (Bujang Valley)، مرورًا بالعصر الذهبي لسلطنة ملقا (Malacca Sultanate)، والحقب الاستعمارية البرتغالية والهولندية والبريطانية، والاحتلال الياباني، والنضال من أجل الاستقلال، وصولًا إلى تشكيل ماليزيا — ترك كل عصر طبقته على أمة اليوم. استكشف تاريخ البلد حسب الحقبة.',
    hi: 'मलेशिया का इतिहास एक वैश्विक चौराहे की कहानी है। बुजांग घाटी (Bujang Valley) के प्राचीन हिंदू-बौद्ध राज्यों से लेकर मलक्का सल्तनत (Malacca Sultanate) के स्वर्ण युग, पुर्तगाली, डच और ब्रिटिश औपनिवेशिक कालों, जापानी कब्ज़े, स्वतंत्रता के संघर्ष, और मलेशिया के गठन तक — प्रत्येक युग ने आज के राष्ट्र पर अपनी एक परत छोड़ी है। युग के अनुसार देश के इतिहास का अन्वेषण करें।',
    es: 'La historia de Malasia es la historia de una encrucijada mundial. Desde los antiguos reinos hindú-budistas del valle de Bujang (Bujang Valley), pasando por la edad de oro del Sultanato de Malaca (Malacca Sultanate), las eras coloniales portuguesa, neerlandesa y británica, la ocupación japonesa, la lucha por la independencia y la formación de Malasia, cada época dejó su huella en la nación de hoy. Explora la historia del país por épocas.',
    fr: "L'histoire de la Malaisie est celle d'un carrefour mondial. Des anciens royaumes hindo-bouddhistes de la vallée de Bujang à l'âge d'or du sultanat de Malacca, des époques coloniales portugaise, néerlandaise et britannique à l'occupation japonaise, de la lutte pour l'indépendance à la formation de la Malaisie, chaque époque a laissé sa strate dans la nation d'aujourd'hui. Explorez l'histoire du pays époque par époque.",
  },
  geography: {
    ms: 'Malaysia terbentang merentasi dua daratan yang dipisahkan Laut China Selatan — Semenanjung di barat dan Borneo di timur. Dari Banjaran Titiwangsa yang menjadi tulang belakang Semenanjung, ke Gunung Kinabalu yang menjulang di Sabah; dari Sungai Rajang yang terpanjang, ke pulau-pulau geopark Langkawi; iklim khatulistiwa dan dua musim monsun membentuk tanah dan kehidupan rakyatnya. Terokai geografi negara mengikut tema.',
    en: "Malaysia stretches across two landmasses split by the South China Sea — the Peninsula in the west and Borneo in the east. From the Titiwangsa Range that forms the Peninsula's spine, to Mount Kinabalu towering over Sabah; from the longest Rajang River, to the geopark islands of Langkawi; an equatorial climate and two monsoon seasons shape the land and its people. Explore the country's geography by theme.",
    zh: '马来西亚横跨被南中国海分隔的两块陆地——西部的半岛与东部的婆罗洲。从构成半岛脊梁的蒂迪旺沙山脉，到耸立于沙巴的京那巴鲁山；从最长的拉让江，到兰卡威的地质公园岛屿；赤道气候与两个季风季节塑造了这片土地及其人民。按主题探索这个国家的地理。',
    ta: 'மலேசியா தென் சீனக் கடலால் பிரிக்கப்பட்ட இரு நிலப்பரப்புகளில் விரிந்து கிடக்கிறது — மேற்கில் தீபகற்பமும் கிழக்கில் போர்னியோவும். தீபகற்பத்தின் முதுகெலும்பாக அமையும் திதிவங்சா மலைத்தொடரிலிருந்து சபாவின் மேல் உயர்ந்து நிற்கும் கினபாலு மலை வரை; மிக நீளமான ராஜாங் ஆற்றிலிருந்து லங்காவியின் புவியியல் பூங்கா தீவுகள் வரை; ஒரு பூமத்திய ரேகைக் காலநிலையும் இரண்டு பருவமழைப் பருவங்களும் இந்த நிலத்தையும் அதன் மக்களையும் வடிவமைக்கின்றன. நாட்டின் புவியியலை கருப்பொருள் வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシアは南シナ海で隔てられた二つの陸塊にまたがっています——西のマレー半島と東のボルネオです。半島の背骨をなすティティワンサ山脈から、サバにそびえるキナバル山へ。最も長いラジャン川から、ランカウイのジオパークの島々へ。赤道気候と二つのモンスーンの季節が、この土地と人々を形づくっています。国の地理をテーマ別に見てみましょう。',
    ko: '말레이시아는 남중국해(South China Sea)로 나뉜 두 개의 땅덩어리에 걸쳐 있습니다 — 서쪽의 반도와 동쪽의 보르네오(Borneo)입니다. 반도의 등뼈를 이루는 티티왕사 산맥(Titiwangsa Range)에서 사바(Sabah)에 우뚝 솟은 키나발루산(Mount Kinabalu)까지, 가장 긴 라장강(Rajang River)에서 랑카위(Langkawi)의 지질공원 섬들까지, 적도 기후와 두 차례의 몬순 계절이 이 땅과 그 사람들을 빚어냅니다. 주제별로 이 나라의 지리를 탐색해 보십시오.',
    th: 'มาเลเซียทอดตัวข้ามผืนแผ่นดินสองส่วนที่ถูกแบ่งด้วยทะเลจีนใต้ (South China Sea) — คาบสมุทรทางตะวันตกและเกาะบอร์เนียว (Borneo) ทางตะวันออก จากเทือกเขาตีตีวังซา (Titiwangsa Range) ที่เป็นสันหลังของคาบสมุทร ไปจนถึงยอดเขากีนาบาลู (Mount Kinabalu) ที่ตระหง่านเหนือรัฐซาบาห์ (Sabah); จากแม่น้ำราจัง (Rajang River) ที่ยาวที่สุด ไปจนถึงหมู่เกาะอุทยานธรณีลังกาวี (Langkawi); ภูมิอากาศแบบเส้นศูนย์สูตรและฤดูมรสุมสองช่วงหล่อหลอมผืนแผ่นดินและผู้คน สำรวจภูมิศาสตร์ของประเทศตามหัวข้อ',
    vi: 'Malaysia trải dài trên hai khối lục địa bị chia cắt bởi Biển Đông (South China Sea) — bán đảo ở phía tây và Borneo ở phía đông. Từ dãy Titiwangsa (Titiwangsa Range) tạo nên xương sống của bán đảo, đến núi Kinabalu (Mount Kinabalu) sừng sững trên Sabah; từ sông Rajang (Rajang River) dài nhất, đến các đảo công viên địa chất của Langkawi; khí hậu xích đạo và hai mùa gió mùa định hình vùng đất và con người nơi đây. Khám phá địa lý đất nước theo chủ đề.',
    id: 'Malaysia terbentang melintasi dua daratan yang dipisahkan oleh Laut China Selatan — Semenanjung di barat dan Borneo di timur. Dari Pegunungan Titiwangsa yang menjadi tulang punggung Semenanjung, hingga Gunung Kinabalu yang menjulang di Sabah; dari Sungai Rajang yang terpanjang, hingga pulau-pulau geopark Langkawi; iklim khatulistiwa dan dua musim monsun membentuk tanah dan kehidupan rakyatnya. Jelajahi geografi negara ini berdasarkan tema.',
    ar: 'تمتد ماليزيا عبر كتلتين أرضيتين يفصل بينهما بحر الصين الجنوبي — شبه الجزيرة في الغرب وبورنيو (Borneo) في الشرق. من سلسلة جبال تيتيوانغسا (Titiwangsa Range) التي تشكّل العمود الفقري لشبه الجزيرة، إلى جبل كينابالو (Mount Kinabalu) الشامخ فوق صباح (Sabah)؛ ومن نهر راجانغ (Rajang River) الأطول، إلى جزر الحديقة الجيولوجية في لنكاوي (Langkawi)؛ يشكّل مناخ استوائي وموسمان من الرياح الموسمية الأرضَ وسكانها. استكشف جغرافيا البلد حسب الموضوع.',
    hi: 'मलेशिया दक्षिण चीन सागर (South China Sea) से विभाजित दो भूभागों में फैला है — पश्चिम में प्रायद्वीप और पूर्व में बोर्नियो (Borneo)। प्रायद्वीप की रीढ़ बनाने वाली तितिवांग्सा श्रेणी (Titiwangsa Range) से लेकर Sabah पर ऊँचे खड़े माउंट किनाबालु (Mount Kinabalu) तक; सबसे लंबी राजांग नदी (Rajang River) से लेकर लंकावी (Langkawi) के भूपार्क द्वीपों तक; एक भूमध्यरेखीय जलवायु और दो मानसून ऋतुएँ इस भूमि और इसके लोगों को आकार देती हैं। विषय के अनुसार देश के भूगोल का अन्वेषण करें।',
    es: 'Malasia se extiende sobre dos masas de tierra separadas por el mar de China Meridional (South China Sea): la Península al oeste y Borneo (Borneo) al este. Desde la cordillera de Titiwangsa (Titiwangsa Range), que forma la columna vertebral de la Península, hasta el monte Kinabalu (Mount Kinabalu), que se alza sobre Sabah; desde el río Rajang (Rajang River), el más largo, hasta las islas del geoparque de Langkawi; un clima ecuatorial y dos estaciones monzónicas moldean la tierra y a su gente. Explora la geografía del país por temas.',
    fr: "La Malaisie s'étend sur deux masses terrestres séparées par la mer de Chine méridionale : la péninsule à l'ouest et Bornéo à l'est. De la chaîne de Titiwangsa, qui forme l'épine dorsale de la péninsule, au mont Kinabalu qui domine le Sabah ; du Rajang, le plus long fleuve, aux îles géoparc de Langkawi ; un climat équatorial et deux saisons de mousson façonnent la terre et ses habitants. Explorez la géographie du pays par thème.",
  },
  culture: {
    ms: 'Budaya Malaysia ialah pertemuan tamadun — Melayu, Cina, India, Peranakan, dan puluhan masyarakat peribumi Sabah dan Sarawak, hidup berjiran selama berabad-abad. Dari perayaan yang penuh warna seperti Hari Raya, Tahun Baru Cina, Deepavali dan Gawai, ke adat perkahwinan, seni mempertahankan diri, dan kraf warisan seperti songket dan wau — kepelbagaian inilah jiwa negara. Terokai budaya Malaysia mengikut tema.',
    en: "Malaysia's culture is a meeting of civilisations — Malay, Chinese, Indian, Peranakan, and dozens of indigenous peoples of Sabah and Sarawak, living side by side for centuries. From colourful festivals like Hari Raya, Chinese New Year, Deepavali and Gawai, to wedding customs, martial arts, and heritage crafts like songket and wau kites — this diversity is the soul of the nation. Explore Malaysian culture by theme.",
    zh: '马来西亚的文化是文明的交汇——马来、华、印、土生华人，以及沙巴和砂拉越数十个原住民族群，数百年来比邻而居。从开斋节、农历新年、屠妖节与丰收节等缤纷节庆，到婚俗、武术，以及宋吉锦缎与风筝等传统工艺——这份多元正是国家的灵魂。按主题探索马来西亚文化。',
    ta: 'மலேசியாவின் பண்பாடு நாகரிகங்களின் சந்திப்பு — மலாய், சீன, இந்திய, பெரானாக்கான் மக்களும், சபா மற்றும் சரவாக்கின் டஜன் கணக்கான பழங்குடி இனங்களும் நூற்றாண்டுகளாக அருகருகே வாழ்ந்து வருகின்றனர். ஹரி ராயா, சீனப் புத்தாண்டு, தீபாவளி, கவாய் போன்ற வண்ணமயமான திருவிழாக்களிலிருந்து, திருமண மரபுகள், தற்காப்புக் கலைகள், சொங்கெட் நெசவு மற்றும் வாவ் காத்தாடி போன்ற பாரம்பரியக் கைவினைகள் வரை — இந்தப் பன்முகத்தன்மையே நாட்டின் ஆன்மா. மலேசியப் பண்பாட்டை கருப்பொருள் வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシアの文化は文明の出会いです——マレー系、華人、インド系、プラナカン、そしてサバとサラワクの数十の先住民が、何世紀にもわたって隣り合って暮らしてきました。ハリラヤ、旧正月、ディーパバリ、ガワイといった色鮮やかな祭りから、婚礼の慣習、護身術、ソンケット織りやワウ（凧）のような伝統工芸まで——この多様性こそが国の魂です。マレーシアの文化をテーマ別に見てみましょう。',
    ko: '말레이시아의 문화는 여러 문명이 만나는 자리입니다 — 말레이계, 중국계, 인도계, 페라나칸(Peranakan), 그리고 사바(Sabah)와 사라왁(Sarawak)의 수십 개 원주민이 수백 년 동안 이웃하여 살아왔습니다. 하리 라야(Hari Raya), 설날, 디파발리(Deepavali), 가와이(Gawai)와 같은 화려한 축제에서부터 혼례 풍습, 무예, 송켓(songket)과 연(wau)과 같은 전통 공예에 이르기까지 — 이 다양성이야말로 국가의 정신입니다. 주제별로 말레이시아 문화를 탐색해 보십시오.',
    th: 'วัฒนธรรมของมาเลเซียคือการบรรจบกันของอารยธรรม — ชาวมลายู ชาวจีน ชาวอินเดีย ชาวเปอรานากัน (Peranakan) และชนพื้นเมืองหลายสิบกลุ่มของรัฐซาบาห์ (Sabah) และรัฐซาราวัก (Sarawak) ซึ่งอยู่ร่วมกันมานานหลายศตวรรษ จากเทศกาลอันมีสีสันอย่างฮารีรายอ (Hari Raya) ตรุษจีน ดีปาวลี (Deepavali) และกาไว (Gawai) ไปจนถึงประเพณีการแต่งงาน ศิลปะการต่อสู้ และงานหัตถกรรมมรดกอย่างผ้าซองเก็ต (songket) และว่าว (wau) — ความหลากหลายนี้คือจิตวิญญาณของชาติ สำรวจวัฒนธรรมมาเลเซียตามหัวข้อ',
    vi: 'Văn hóa Malaysia là sự gặp gỡ của các nền văn minh — người Mã Lai, người Hoa, người Ấn, người Peranakan, cùng hàng chục cộng đồng bản địa của Sabah và Sarawak, sống bên nhau qua nhiều thế kỷ. Từ những lễ hội rực rỡ sắc màu như Hari Raya, Tết Nguyên đán của người Hoa, Deepavali và Gawai, đến các phong tục cưới hỏi, võ thuật, và những nghề thủ công di sản như songket và diều wau — chính sự đa dạng này là linh hồn của dân tộc. Khám phá văn hóa Malaysia theo chủ đề.',
    id: 'Budaya Malaysia adalah pertemuan peradaban — Melayu, Tionghoa, India, Peranakan, dan puluhan masyarakat adat Sabah dan Sarawak, hidup berdampingan selama berabad-abad. Dari perayaan yang penuh warna seperti Hari Raya, Tahun Baru Imlek, Deepavali, dan Gawai, hingga adat pernikahan, seni bela diri, dan kerajinan warisan seperti songket dan wau — keberagaman inilah jiwa bangsa. Jelajahi budaya Malaysia berdasarkan tema.',
    ar: 'ثقافة ماليزيا لقاء حضارات — الملايو والصينيون والهنود والبيرانكان (Peranakan) وعشرات الشعوب الأصلية في صباح (Sabah) وساراواك (Sarawak)، عاشوا جنبًا إلى جنب على مدى قرون. من المهرجانات الزاهية مثل عيد الفطر (Hari Raya) ورأس السنة الصينية وديبافالي (Deepavali) وغاواي (Gawai)، إلى عادات الزفاف والفنون القتالية والحرف التراثية مثل السونغكيت (songket) وطائرات الواو الورقية (wau) — هذا التنوع هو روح الأمة. استكشف الثقافة الماليزية حسب الموضوع.',
    hi: 'मलेशिया की संस्कृति सभ्यताओं का मिलन है — मलय, चीनी, भारतीय, पेरानाकन (Peranakan), और Sabah तथा Sarawak के दर्जनों मूलनिवासी समुदाय, सदियों से साथ-साथ रहते आए हैं। Hari Raya, चीनी नववर्ष, दीपावली और Gawai जैसे रंगारंग त्योहारों से लेकर विवाह की रीतियों, मार्शल आर्ट्स, और songket तथा wau पतंगों जैसी विरासती शिल्पकलाओं तक — यही विविधता राष्ट्र की आत्मा है। विषय के अनुसार मलेशियाई संस्कृति का अन्वेषण करें।',
    es: 'La cultura de Malasia es un encuentro de civilizaciones: malaya, china, india, peranakan (Peranakan) y decenas de pueblos indígenas de Sabah y Sarawak, que conviven desde hace siglos. Desde festivales llenos de color como Hari Raya, el Año Nuevo chino, Deepavali y Gawai, hasta las costumbres nupciales, las artes marciales y las artesanías patrimoniales como el songket y las cometas wau, esta diversidad es el alma de la nación. Explora la cultura malasia por temas.',
    fr: "La culture malaisienne est une rencontre de civilisations : malaise, chinoise, indienne, peranakan et des dizaines de peuples autochtones du Sabah et du Sarawak, qui vivent côte à côte depuis des siècles. Des fêtes hautes en couleur comme Hari Raya, le Nouvel An chinois, Deepavali et Gawai aux coutumes de mariage, aux arts martiaux et aux artisanats patrimoniaux comme le songket et les cerfs-volants wau, cette diversité est l'âme de la nation. Explorez la culture malaisienne par thème.",
  },
  states: {
    ms: 'Malaysia terdiri daripada 13 negeri dan 3 wilayah persekutuan. Sembilan negeri Melayu mengekalkan Sultan atau Raja mereka; setiap negeri mempunyai sejarah, dialek, masakan, dan keperibadian tersendiri — dari Perlis yang mungil di utara, ke Johor di hujung selatan, merentasi Laut China Selatan ke Sabah dan Sarawak di Borneo. Terokai negeri dan wilayah mengikut rantau.',
    en: 'Malaysia is made up of 13 states and 3 federal territories. Nine Malay states retain their Sultans or Rulers; each state has its own history, dialect, cuisine, and personality — from tiny Perlis in the north, to Johor at the southern tip, across the South China Sea to Sabah and Sarawak on Borneo. Explore the states and territories by region.',
    zh: '马来西亚由 13 个州和 3 个联邦直辖区组成。九个马来州保留其苏丹或统治者；每个州都有自己的历史、方言、美食与个性——从北部小小的玻璃市，到最南端的柔佛，越过南中国海到婆罗洲的沙巴与砂拉越。按地区探索各州与直辖区。',
    ta: 'மலேசியா 13 மாநிலங்களையும் 3 கூட்டாட்சிப் பகுதிகளையும் கொண்டது. ஒன்பது மலாய் மாநிலங்கள் தமது சுல்தான்களையோ அரசர்களையோ தக்கவைத்துக் கொண்டுள்ளன; ஒவ்வொரு மாநிலத்திற்கும் தனக்கே உரிய வரலாறு, வட்டார மொழி, உணவு மற்றும் தனித்தன்மை உண்டு — வடக்கே சிறிய பெர்லிஸ் முதல் தென் முனையில் உள்ள ஜொகூர் வரை, தென் சீனக் கடலைக் கடந்து போர்னியோவில் உள்ள சபா மற்றும் சரவாக் வரை. மாநிலங்களையும் பகுதிகளையும் வட்டாரம் வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシアは13の州と3つの連邦直轄区から成ります。9つのマレー系の州はスルタンまたは統治者を戴いています。それぞれの州が独自の歴史、方言、料理、個性を持ち——北の小さなパーリスから、南端のジョホール、南シナ海を越えてボルネオのサバとサラワクまで広がります。州と直轄区を地域別に見てみましょう。',
    ko: '말레이시아는 13개 주와 3개 연방 직할구로 이루어져 있습니다. 아홉 개의 말레이 주는 각자의 술탄(Sultan) 또는 통치자를 유지하고 있으며, 각 주는 저마다의 역사, 방언, 요리, 개성을 지니고 있습니다 — 북쪽의 작은 프를리스(Perlis)에서 남쪽 끝의 조호르(Johor)까지, 남중국해를 건너 보르네오(Borneo)의 사바(Sabah)와 사라왁(Sarawak)까지 이릅니다. 지역별로 주와 직할구를 탐색해 보십시오.',
    th: 'มาเลเซียประกอบด้วย 13 รัฐและ 3 ดินแดนสหพันธ์ รัฐมลายูเก้ารัฐยังคงมีสุลต่านหรือเจ้าผู้ครองของตน; แต่ละรัฐมีประวัติศาสตร์ ภาษาถิ่น อาหาร และเอกลักษณ์เฉพาะตัว — จากรัฐปะลิส (Perlis) อันเล็กจิ๋วทางเหนือ ไปจนถึงรัฐยะโฮร์ (Johor) ที่ปลายสุดทางใต้ ข้ามทะเลจีนใต้ (South China Sea) ไปยังรัฐซาบาห์ (Sabah) และรัฐซาราวัก (Sarawak) บนเกาะบอร์เนียว (Borneo) สำรวจรัฐและดินแดนต่าง ๆ ตามภูมิภาค',
    vi: 'Malaysia gồm 13 bang và 3 lãnh thổ liên bang. Chín bang Mã Lai vẫn duy trì các Sultan hoặc Quân vương của mình; mỗi bang có lịch sử, phương ngữ, ẩm thực và bản sắc riêng — từ Perlis nhỏ bé ở phía bắc, đến Johor ở mũi cực nam, băng qua Biển Đông (South China Sea) đến Sabah và Sarawak trên đảo Borneo. Khám phá các bang và lãnh thổ theo vùng.',
    id: 'Malaysia terdiri dari 13 negara bagian dan 3 wilayah persekutuan. Sembilan negara bagian Melayu mempertahankan Sultan atau Raja mereka; setiap negara bagian memiliki sejarah, dialek, masakan, dan kepribadian tersendiri — dari Perlis yang mungil di utara, hingga Johor di ujung selatan, melintasi Laut China Selatan ke Sabah dan Sarawak di Borneo. Jelajahi negara bagian dan wilayah berdasarkan kawasan.',
    ar: 'تتكوّن ماليزيا من 13 ولاية و3 أقاليم اتحادية. تحتفظ تسع ولايات ملايوية بسلاطينها أو حكّامها؛ ولكل ولاية تاريخها ولهجتها ومطبخها وشخصيتها — من ولاية بيرليس (Perlis) الصغيرة في الشمال، إلى ولاية جوهور (Johor) في الطرف الجنوبي، عبر بحر الصين الجنوبي إلى صباح (Sabah) وساراواك (Sarawak) في بورنيو (Borneo). استكشف الولايات والأقاليم حسب المنطقة.',
    hi: 'मलेशिया 13 राज्यों और 3 संघीय क्षेत्रों से मिलकर बना है। नौ मलय राज्य अपने सुल्तानों या शासकों को बनाए रखते हैं; प्रत्येक राज्य का अपना इतिहास, बोली, व्यंजन और व्यक्तित्व है — उत्तर में छोटे-से Perlis से लेकर दक्षिणी छोर पर Johor तक, दक्षिण चीन सागर (South China Sea) के पार बोर्नियो (Borneo) पर Sabah और Sarawak तक। क्षेत्र के अनुसार राज्यों और क्षेत्रों का अन्वेषण करें।',
    es: 'Malasia está compuesta por 13 estados y 3 territorios federales. Nueve estados malayos conservan a sus sultanes o soberanos; cada estado tiene su propia historia, dialecto, gastronomía y personalidad, desde el diminuto Perlis en el norte hasta Johor en el extremo sur, cruzando el mar de China Meridional (South China Sea) hacia Sabah y Sarawak en Borneo (Borneo). Explora los estados y territorios por región.',
    fr: "La Malaisie se compose de 13 États et de 3 territoires fédéraux. Neuf États malais conservent leurs sultans ou leurs souverains ; chaque État possède sa propre histoire, son dialecte, sa cuisine et sa personnalité, du minuscule Perlis au nord à Johor à la pointe sud, et, de l'autre côté de la mer de Chine méridionale, jusqu'au Sabah et au Sarawak sur l'île de Bornéo. Explorez les États et les territoires par région.",
  },
  food: {
    ms: 'Makanan Malaysia ialah cerminan masyarakat majmuknya — pertemuan cita rasa Melayu, Cina, India, dan peribumi dalam satu pinggan. Dari nasi lemak dan laksa ke roti canai dan char kway teow, dari teh tarik di gerai mamak ke durian "raja buah" — makanan menyatukan rakyat merentasi kaum dan kelas. Terokai warisan masakan negara mengikut jenis.',
    en: "Malaysian food mirrors its plural society — a meeting of Malay, Chinese, Indian and indigenous flavours on one plate. From nasi lemak and laksa to roti canai and char kway teow, from teh tarik at the mamak stall to the durian 'king of fruits' — food unites people across race and class. Explore the country's culinary heritage by type.",
    zh: '马来西亚美食是其多元社会的写照——马来、华、印与原住民风味在一盘中交汇。从椰浆饭、叻沙到印度煎饼、炒粿条，从嘛嘛档的拉茶到“果王”榴莲——美食跨越种族与阶层，凝聚人民。按类别探索这个国家的烹饪传统。',
    ta: 'மலேசிய உணவு அதன் பன்முக சமூகத்தின் பிரதிபலிப்பு — மலாய், சீன, இந்திய மற்றும் பழங்குடி சுவைகள் ஒரே தட்டில் சந்திக்கின்றன. நாசி லெமாக், லக்சா முதல் ரொட்டி சானாய், சார் குவே தியாவ் வரை, மாமாக் கடையின் தே தாரிக் முதல் “பழங்களின் அரசன்” துரியான் வரை — உணவு இனத்தையும் வர்க்கத்தையும் கடந்து மக்களை ஒன்றிணைக்கிறது. நாட்டின் சமையல் பாரம்பரியத்தை வகை வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシア料理は多民族社会の映し鏡です——マレー系、華人、インド系、先住民の味わいが一皿で出会います。ナシルマッやラクサから、ロティチャナイやチャークイティアオまで、ママック屋台のテータレッから「果物の王」ドリアンまで——食は民族や階層を越えて人々を結びつけます。国の食の伝統を種類別に見てみましょう。',
    ko: '말레이시아 음식은 다원 사회를 비추는 거울입니다 — 말레이계, 중국계, 인도계, 원주민의 맛이 한 접시에서 만납니다. 나시 르막(nasi lemak)과 락사(laksa)에서 로티 차나이(roti canai)와 차 궤 테오(char kway teow)까지, 마막(mamak) 노점의 테 타릭(teh tarik)에서 “과일의 왕” 두리안(durian)까지 — 음식은 민족과 계층을 넘어 사람들을 하나로 묶습니다. 종류별로 이 나라의 음식 유산을 탐색해 보십시오.',
    th: 'อาหารมาเลเซียสะท้อนสังคมพหุวัฒนธรรมของประเทศ — การบรรจบกันของรสชาติมลายู จีน อินเดีย และชนพื้นเมืองในจานเดียว จากนาซีเลอมัก (nasi lemak) และลักซา (laksa) ไปจนถึงโรตีจาไน (roti canai) และช่าร์กุยเตียว (char kway teow) จากเตทาริก (teh tarik) ที่ร้านมามัก (mamak) ไปจนถึงทุเรียน (durian) “ราชาแห่งผลไม้” — อาหารเชื่อมผู้คนเข้าด้วยกันข้ามเชื้อชาติและชนชั้น สำรวจมรดกด้านอาหารของประเทศตามประเภท',
    vi: 'Ẩm thực Malaysia phản chiếu xã hội đa nguyên của đất nước — sự gặp gỡ của các hương vị Mã Lai, Hoa, Ấn và bản địa trên cùng một đĩa. Từ nasi lemak và laksa đến roti canai và char kway teow, từ teh tarik tại quầy mamak đến sầu riêng (durian) “vua của các loại trái cây” — ẩm thực gắn kết con người vượt qua ranh giới sắc tộc và giai tầng. Khám phá di sản ẩm thực của đất nước theo từng loại.',
    id: 'Makanan Malaysia adalah cerminan masyarakat majemuknya — pertemuan cita rasa Melayu, Tionghoa, India, dan pribumi dalam satu piring. Dari nasi lemak dan laksa hingga roti canai dan char kway teow, dari teh tarik di gerai mamak hingga durian "raja buah" — makanan menyatukan rakyat melintasi suku dan kelas. Jelajahi warisan kuliner negara ini berdasarkan jenis.',
    ar: 'يعكس الطعام الماليزي مجتمعه التعددي — لقاء نكهات الملايو والصينيين والهنود والشعوب الأصلية في طبق واحد. من ناسي ليماك (nasi lemak) واللاكسا (laksa) إلى روتي تشاناي (roti canai) وتشار كوي تياو (char kway teow)، ومن الشاي المسحوب (teh tarik) في كشك الماماك (mamak) إلى الدوريان (durian) "ملك الفواكه" — يوحّد الطعام الناس عبر العِرق والطبقة. استكشف التراث الطهوي للبلد حسب النوع.',
    hi: 'मलेशियाई भोजन इसके बहुलवादी समाज का दर्पण है — एक ही थाली में मलय, चीनी, भारतीय और मूलनिवासी स्वादों का मिलन। nasi lemak और laksa से लेकर roti canai और char kway teow तक, mamak स्टॉल की teh tarik से लेकर "फलों के राजा" durian तक — भोजन लोगों को नस्ल और वर्ग से परे जोड़ता है। प्रकार के अनुसार देश की पाक-विरासत का अन्वेषण करें।',
    es: 'La comida malasia refleja su sociedad plural: un encuentro de sabores malayos, chinos, indios e indígenas en un mismo plato. Desde el nasi lemak y el laksa hasta el roti canai y el char kway teow, desde el teh tarik del puesto mamak hasta el durián, «el rey de las frutas», la comida une a las personas más allá de la raza y la clase. Explora el patrimonio culinario del país por tipo.',
    fr: "La cuisine malaisienne est le miroir de sa société plurielle : une rencontre de saveurs malaises, chinoises, indiennes et autochtones dans une même assiette. Du nasi lemak et du laksa au roti canai et au char kway teow, du teh tarik de l'échoppe mamak au durian, « roi des fruits », la nourriture unit les gens par-delà l'origine ethnique et la classe sociale. Explorez le patrimoine culinaire du pays par type.",
  },
  people: {
    ms: 'Malaysia dibentuk oleh tokoh-tokohnya — perdana menteri yang memimpin negara ke merdeka dan pembangunan, seniman dan penghibur yang mencorak budaya, atlet yang mengharumkan nama negara, serta perintis sains yang membuka jalan baharu. Terokai tokoh yang membentuk negara mengikut bidang.',
    en: 'Malaysia is shaped by its people — prime ministers who led the nation to independence and development, artists and entertainers who defined its culture, athletes who brought it glory, and science pioneers who opened new paths. Explore the figures who shaped the nation by field.',
    zh: '马来西亚由其人物塑造——带领国家走向独立与发展的首相、定义文化的艺术家与艺人、为国争光的运动员，以及开辟新路的科学先驱。按领域探索塑造国家的人物。',
    ta: 'மலேசியாவை அதன் மக்களே வடிவமைத்தனர் — நாட்டை சுதந்திரத்திற்கும் வளர்ச்சிக்கும் வழிநடத்திய பிரதமர்கள், பண்பாட்டை வரையறுத்த கலைஞர்களும் கலைஞர்களும், நாட்டுக்குப் புகழ் தேடித்தந்த விளையாட்டு வீரர்கள், புதிய பாதைகளைத் திறந்த அறிவியல் முன்னோடிகள். நாட்டை வடிவமைத்த ஆளுமைகளை துறை வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシアは、その人物たちによって形づくられてきました——国を独立と発展へ導いた首相たち、文化を定義した芸術家や芸能人、国に栄光をもたらしたアスリート、新たな道を切り開いた科学の先駆者たち。国を形づくった人物を分野別に見てみましょう。',
    ko: '말레이시아는 그 인물들에 의해 형성되어 왔습니다 — 나라를 독립과 발전으로 이끈 총리들, 문화를 규정한 예술가와 연예인들, 나라에 영광을 안긴 운동선수들, 그리고 새로운 길을 연 과학 선구자들입니다. 국가를 형성한 인물들을 분야별로 탐색해 보십시오.',
    th: 'มาเลเซียถูกหล่อหลอมโดยผู้คนของประเทศ — นายกรัฐมนตรีผู้นำชาติสู่เอกราชและการพัฒนา ศิลปินและผู้ให้ความบันเทิงผู้นิยามวัฒนธรรม นักกีฬาผู้นำเกียรติยศมาสู่ประเทศ และผู้บุกเบิกทางวิทยาศาสตร์ผู้เปิดเส้นทางใหม่ สำรวจบุคคลผู้หล่อหลอมชาติตามสาขา',
    vi: 'Malaysia được định hình bởi con người của mình — những thủ tướng đã dẫn dắt đất nước đến độc lập và phát triển, những nghệ sĩ và người làm giải trí đã định hình nền văn hóa, những vận động viên đã mang lại vinh quang, và những người tiên phong khoa học đã mở ra những con đường mới. Khám phá những nhân vật đã định hình dân tộc theo từng lĩnh vực.',
    id: 'Malaysia dibentuk oleh tokoh-tokohnya — perdana menteri yang memimpin negara menuju kemerdekaan dan pembangunan, seniman dan penghibur yang mewarnai budaya, atlet yang mengharumkan nama negara, serta perintis sains yang membuka jalan baru. Jelajahi tokoh yang membentuk bangsa ini berdasarkan bidang.',
    ar: 'تتشكّل ماليزيا بشخصياتها — رؤساء وزراء قادوا الأمة إلى الاستقلال والتنمية، وفنانون ومؤدّون رسموا ثقافتها، ورياضيون جلبوا لها المجد، ورواد علم فتحوا دروبًا جديدة. استكشف الشخصيات التي شكّلت الأمة حسب المجال.',
    hi: 'मलेशिया को इसके लोगों ने आकार दिया है — वे प्रधानमंत्री जिन्होंने राष्ट्र को स्वतंत्रता और विकास की ओर अग्रसर किया, वे कलाकार और मनोरंजनकर्ता जिन्होंने इसकी संस्कृति को परिभाषित किया, वे खिलाड़ी जो इसके लिए गौरव लाए, और वे विज्ञान के अग्रदूत जिन्होंने नए रास्ते खोले। क्षेत्र के अनुसार राष्ट्र को आकार देने वाली हस्तियों का अन्वेषण करें।',
    es: 'Malasia está moldeada por su gente: primeros ministros que llevaron a la nación a la independencia y el desarrollo, artistas y figuras del espectáculo que definieron su cultura, atletas que le dieron gloria y pioneros de la ciencia que abrieron nuevos caminos. Explora las figuras que moldearon la nación por campo.',
    fr: "La Malaisie est façonnée par ses habitants : des Premiers ministres qui ont mené la nation à l'indépendance et au développement, des artistes et des figures du spectacle qui ont défini sa culture, des athlètes qui l'ont couverte de gloire et des pionniers de la science qui ont ouvert de nouvelles voies. Explorez, par domaine, les figures qui ont façonné la nation.",
  },
  religion: {
    ms: 'Malaysia ialah sebuah negara berbilang agama. Islam ialah agama persekutuan, sementara Perlembagaan menjamin kebebasan beragama bagi penganut Buddha, Hindu, Kristian, dan kepercayaan lain. Masjid, tokong, kuil, dan gereja berdiri berdekatan — cerminan keharmonian yang menjadi teras masyarakat majmuk. Terokai agama dan amalan di Malaysia.',
    en: "Malaysia is a multireligious nation. Islam is the religion of the federation, while the Constitution guarantees freedom of worship for Buddhists, Hindus, Christians, and others. Mosques, temples, and churches stand side by side — a reflection of the harmony at the heart of a plural society. Explore Malaysia's religions and practices.",
    zh: '马来西亚是一个多宗教国家。伊斯兰教是联邦宗教，而宪法保障佛教、印度教、基督教及其他信仰者的宗教自由。清真寺、庙宇与教堂比邻而立——正是多元社会核心和谐的写照。探索马来西亚的宗教与习俗。',
    ta: 'மலேசியா ஒரு பல்சமய நாடு. இஸ்லாம் கூட்டமைப்பின் மதம்; அதே வேளையில் அரசியலமைப்பு பௌத்தர்கள், இந்துக்கள், கிறிஸ்தவர்கள் மற்றும் பிறருக்கு வழிபாட்டு சுதந்திரத்தை உறுதி செய்கிறது. மசூதிகள், கோயில்கள், தேவாலயங்கள் அருகருகே நிற்கின்றன — பன்முக சமூகத்தின் மையத்தில் அமைந்துள்ள இணக்கத்தின் பிரதிபலிப்பு. மலேசியாவின் மதங்களையும் வழக்கங்களையும் ஆராயுங்கள்.',
    ja: 'マレーシアは多宗教の国です。イスラム教は連邦の宗教であり、同時に憲法は仏教徒、ヒンドゥー教徒、キリスト教徒、その他の信者に信仰の自由を保障しています。モスク、廟、寺院、教会が隣り合って建ち——多元社会の核心にある調和を映し出しています。マレーシアの宗教と慣習を見てみましょう。',
    ko: '말레이시아는 다종교 국가입니다. 이슬람교는 연방의 종교이며, 동시에 헌법은 불교도, 힌두교도, 기독교도를 비롯한 이들에게 신앙의 자유를 보장합니다. 모스크와 사원, 교회가 나란히 서 있습니다 — 다원 사회의 중심에 자리한 조화를 비추어 보여 줍니다. 말레이시아의 종교와 관습을 탐색해 보십시오.',
    th: 'มาเลเซียเป็นชาติที่มีหลายศาสนา ศาสนาอิสลามเป็นศาสนาของสหพันธรัฐ ขณะที่รัฐธรรมนูญรับรองเสรีภาพในการนับถือศาสนาแก่ชาวพุทธ ชาวฮินดู ชาวคริสต์ และผู้นับถือศาสนาอื่น ๆ มัสยิด วัด และโบสถ์ตั้งอยู่เคียงข้างกัน — สะท้อนความกลมเกลียวอันเป็นหัวใจของสังคมพหุวัฒนธรรม สำรวจศาสนาและวัตรปฏิบัติของมาเลเซีย',
    vi: 'Malaysia là một quốc gia đa tôn giáo. Hồi giáo là tôn giáo của liên bang, trong khi Hiến pháp bảo đảm quyền tự do tín ngưỡng cho các tín đồ Phật giáo, Hindu giáo, Kitô giáo và các tín ngưỡng khác. Các thánh đường Hồi giáo, đền, chùa và nhà thờ đứng cạnh nhau — phản ánh sự hòa hợp nằm ở trung tâm của một xã hội đa nguyên. Khám phá các tôn giáo và tập tục của Malaysia.',
    id: 'Malaysia adalah sebuah negara multiagama. Islam adalah agama federasi, sementara Konstitusi menjamin kebebasan beragama bagi penganut Buddha, Hindu, Kristen, dan kepercayaan lain. Masjid, kelenteng, kuil, dan gereja berdiri berdampingan — cerminan keharmonisan yang menjadi inti masyarakat majemuk. Jelajahi agama dan praktik keagamaan di Malaysia.',
    ar: 'ماليزيا أمة متعددة الأديان. الإسلام دين الاتحاد، في حين يكفل الدستور حرية العبادة للبوذيين والهندوس والمسيحيين وغيرهم. تقف المساجد والمعابد والكنائس جنبًا إلى جنب — انعكاسًا للوئام الذي يقع في صميم مجتمع تعددي. استكشف أديان ماليزيا وممارساتها.',
    hi: 'मलेशिया एक बहुधार्मिक राष्ट्र है। इस्लाम संघ का धर्म है, जबकि संविधान बौद्धों, हिंदुओं, ईसाइयों और अन्य लोगों के लिए उपासना की स्वतंत्रता की गारंटी देता है। मस्जिदें, मंदिर और गिरजाघर साथ-साथ खड़े हैं — एक बहुलवादी समाज के केंद्र में बसी सद्भावना का प्रतिबिंब। मलेशिया के धर्मों और प्रथाओं का अन्वेषण करें।',
    es: 'Malasia es una nación multirreligiosa. El islam es la religión de la federación, mientras que la Constitución garantiza la libertad de culto a budistas, hindúes, cristianos y otros. Mezquitas, templos e iglesias se alzan unos junto a otros, reflejo de la armonía en el corazón de una sociedad plural. Explora las religiones y prácticas de Malasia.',
    fr: "La Malaisie est une nation multireligieuse. L'islam est la religion de la Fédération, tandis que la Constitution garantit la liberté de culte aux bouddhistes, aux hindous, aux chrétiens et à d'autres. Mosquées, temples et églises se dressent côte à côte, reflet de l'harmonie au cœur d'une société plurielle. Explorez les religions et les pratiques de la Malaisie.",
  },
  nature: {
    ms: 'Malaysia ialah antara 17 negara "megadiversiti" di dunia. Hutan hujan purba Borneo dan Semenanjung menaungi orang utan, harimau Malaya, dan bunga Rafflesia; laut dan terumbu karangnya penuh hidupan marin. Namun kekayaan ini berdepan tekanan pembangunan. Terokai alam semula jadi negara dan usaha memeliharanya.',
    en: "Malaysia is one of the world's 17 'megadiverse' countries. The ancient rainforests of Borneo and the Peninsula shelter orangutans, the Malayan tiger, and the Rafflesia flower; its seas and reefs teem with marine life. Yet this wealth faces the pressures of development. Explore the country's nature and the efforts to protect it.",
    zh: '马来西亚是全球 17 个“超级生物多样性”国家之一。婆罗洲与半岛的远古雨林庇护着红毛猩猩、马来虎与大王花；海洋与珊瑚礁充满海洋生物。然而这份财富正面临发展的压力。探索这个国家的自然及其保育努力。',
    ta: 'மலேசியா உலகின் 17 “பேரியல்பு பல்லுயிரியப்” நாடுகளில் ஒன்று. போர்னியோவின் மற்றும் தீபகற்பத்தின் பழம்பெரும் மழைக்காடுகள் ஒராங்குட்டான்களுக்கும், மலாயா புலிக்கும், ரஃப்ளேசியா மலருக்கும் அடைக்கலம் தருகின்றன; அதன் கடல்களும் பவளப்பாறைகளும் கடல்வாழ் உயிரினங்களால் நிறைந்துள்ளன. ஆயினும் இந்தச் செல்வம் வளர்ச்சியின் அழுத்தங்களை எதிர்கொள்கிறது. நாட்டின் இயற்கையையும் அதைப் பாதுகாக்கும் முயற்சிகளையும் ஆராயுங்கள்.',
    ja: 'マレーシアは世界に17ある「メガダイバーシティ（生物多様性大国）」の一つです。ボルネオと半島の太古の熱帯雨林は、オランウータン、マレートラ、ラフレシアの花を育みます。海とサンゴ礁は海洋生物であふれています。しかしこの豊かさは開発の圧力に直面しています。国の自然とその保護の取り組みを見てみましょう。',
    ko: '말레이시아는 세계 17개 “메가다양성(megadiverse)” 국가 가운데 하나입니다. 보르네오(Borneo)와 반도의 태고 열대우림은 오랑우탄, 말라야호랑이, 라플레시아(Rafflesia) 꽃을 품고 있으며, 그 바다와 산호초는 해양 생물로 가득합니다. 그러나 이 풍요로움은 개발의 압력에 직면해 있습니다. 이 나라의 자연과 그것을 지키려는 노력을 탐색해 보십시오.',
    th: 'มาเลเซียเป็นหนึ่งใน 17 ประเทศ “ความหลากหลายทางชีวภาพสูงยิ่ง” (megadiverse) ของโลก ป่าฝนโบราณของเกาะบอร์เนียว (Borneo) และคาบสมุทรเป็นที่พักพิงของลิงอุรังอุตัง เสือโคร่งมลายู และดอกบัวผุด (Rafflesia); ทะเลและแนวปะการังเต็มไปด้วยสิ่งมีชีวิตในทะเล ทว่าความมั่งคั่งนี้กำลังเผชิญแรงกดดันจากการพัฒนา สำรวจธรรมชาติของประเทศและความพยายามในการปกป้องรักษา',
    vi: 'Malaysia là một trong 17 quốc gia “đa dạng sinh học bậc nhất” (megadiverse) của thế giới. Những khu rừng mưa cổ xưa của Borneo và bán đảo là nơi trú ngụ của đười ươi, hổ Mã Lai và hoa Rafflesia; biển và các rạn san hô của đất nước tràn đầy sinh vật biển. Tuy nhiên, sự giàu có này đang đối mặt với những áp lực của phát triển. Khám phá thiên nhiên của đất nước và những nỗ lực bảo vệ nó.',
    id: 'Malaysia adalah salah satu dari 17 negara "megadiversitas" di dunia. Hutan hujan kuno Borneo dan Semenanjung menaungi orang utan, harimau Malaya, dan bunga Rafflesia; laut dan terumbu karangnya penuh dengan kehidupan laut. Namun kekayaan ini menghadapi tekanan pembangunan. Jelajahi alam negara ini dan upaya pelestariannya.',
    ar: 'ماليزيا واحدة من 17 دولة في العالم تُوصف بأنها "شديدة التنوع البيولوجي" (megadiverse). تأوي الغابات المطيرة القديمة في بورنيو (Borneo) وشبه الجزيرة إنسان الغاب والنمر الملايوي وزهرة الرفليسيا (Rafflesia)؛ وتعجّ بحارها وشعابها المرجانية بالحياة البحرية. غير أن هذه الثروة تواجه ضغوط التنمية. استكشف طبيعة البلد والجهود المبذولة لحمايتها.',
    hi: 'मलेशिया दुनिया के उन 17 देशों में से एक है जिन्हें "महाविविध" (megadiverse) कहा जाता है। बोर्नियो (Borneo) और प्रायद्वीप के प्राचीन वर्षावन ओरंगुटान, मलायी बाघ और Rafflesia पुष्प को आश्रय देते हैं; इसके समुद्र और प्रवाल भित्तियाँ समुद्री जीवन से भरी हैं। फिर भी यह संपदा विकास के दबावों का सामना कर रही है। देश की प्रकृति और उसे बचाने के प्रयासों का अन्वेषण करें।',
    es: 'Malasia es uno de los 17 países «megadiversos» del mundo. Las antiguas selvas tropicales de Borneo (Borneo) y la Península albergan orangutanes, al tigre malayo y a la flor Rafflesia; sus mares y arrecifes rebosan de vida marina. Sin embargo, esta riqueza se enfrenta a las presiones del desarrollo. Explora la naturaleza del país y los esfuerzos por protegerla.',
    fr: "La Malaisie est l'un des 17 pays « mégadivers » du monde. Les forêts tropicales ancestrales de Bornéo et de la péninsule abritent les orangs-outans, le tigre de Malaisie et la fleur Rafflesia ; ses mers et ses récifs regorgent de vie marine. Pourtant, cette richesse est soumise aux pressions du développement. Explorez la nature du pays et les efforts déployés pour la protéger.",
  },
  society: {
    ms: 'Masyarakat Malaysia ialah mozek berbilang kaum, agama, dan bahasa — Melayu, Cina, India, dan peribumi Sabah dan Sarawak. Dari sistem pendidikan berbilang aliran, penjagaan kesihatan awam, ke kehidupan bandar yang pesat — negara sentiasa mengimbangi kepelbagaian dengan perpaduan. Terokai masyarakat dan sistem sosial Malaysia.',
    en: "Malaysian society is a mosaic of races, religions, and languages — Malay, Chinese, Indian, and the indigenous peoples of Sabah and Sarawak. From a multi-stream education system and public healthcare to fast-growing urban life — the nation constantly balances diversity with unity. Explore Malaysia's society and social systems.",
    zh: '马来西亚社会是种族、宗教与语言的马赛克——马来、华、印，以及沙巴和砂拉越的原住民。从多源流教育体系、公共医疗，到快速发展的城市生活——国家不断在多元与团结之间取得平衡。探索马来西亚的社会与社会体系。',
    ta: 'மலேசிய சமூகம் இனங்கள், மதங்கள், மொழிகளின் ஒரு சித்திரத் தொகுப்பு — மலாய், சீன, இந்திய மக்களும், சபா மற்றும் சரவாக்கின் பழங்குடி மக்களும். பல்வழி கல்வி முறை, பொது சுகாதாரம் முதல் விரைவாக வளரும் நகர வாழ்க்கை வரை — நாடு தொடர்ந்து பன்முகத்தன்மையையும் ஒற்றுமையையும் சமன் செய்து வருகிறது. மலேசியாவின் சமூகத்தையும் சமூக அமைப்புகளையும் ஆராயுங்கள்.',
    ja: 'マレーシア社会は民族、宗教、言語のモザイクです——マレー系、華人、インド系、そしてサバとサラワクの先住民。多流派の教育制度や公的医療から、急速に成長する都市生活まで——国は常に多様性と統合の均衡をとっています。マレーシアの社会と社会制度を見てみましょう。',
    ko: '말레이시아 사회는 민족, 종교, 언어의 모자이크입니다 — 말레이계, 중국계, 인도계, 그리고 사바(Sabah)와 사라왁(Sarawak)의 원주민입니다. 다원화된 교육 제도와 공공 의료에서부터 빠르게 성장하는 도시 생활에 이르기까지 — 국가는 끊임없이 다양성과 통합의 균형을 잡아 갑니다. 말레이시아의 사회와 사회 제도를 탐색해 보십시오.',
    th: 'สังคมมาเลเซียเป็นภาพโมเสกของเชื้อชาติ ศาสนา และภาษา — ชาวมลายู ชาวจีน ชาวอินเดีย และชนพื้นเมืองของรัฐซาบาห์ (Sabah) และรัฐซาราวัก (Sarawak) จากระบบการศึกษาหลายสายและการสาธารณสุข ไปจนถึงชีวิตในเมืองที่เติบโตอย่างรวดเร็ว — ประเทศต้องรักษาสมดุลระหว่างความหลากหลายกับความเป็นเอกภาพอยู่เสมอ สำรวจสังคมและระบบสังคมของมาเลเซีย',
    vi: 'Xã hội Malaysia là một bức khảm của các sắc tộc, tôn giáo và ngôn ngữ — người Mã Lai, người Hoa, người Ấn, và các dân tộc bản địa của Sabah và Sarawak. Từ hệ thống giáo dục đa dòng và y tế công cộng đến đời sống đô thị phát triển nhanh chóng — đất nước không ngừng cân bằng giữa sự đa dạng và sự đoàn kết. Khám phá xã hội và các hệ thống xã hội của Malaysia.',
    id: 'Masyarakat Malaysia adalah mozaik dari berbagai suku, agama, dan bahasa — Melayu, Tionghoa, India, dan masyarakat adat Sabah dan Sarawak. Dari sistem pendidikan multialiran, layanan kesehatan publik, hingga kehidupan kota yang pesat — negara senantiasa menyeimbangkan keberagaman dengan persatuan. Jelajahi masyarakat dan sistem sosial Malaysia.',
    ar: 'المجتمع الماليزي فسيفساء من الأعراق والأديان واللغات — الملايو والصينيون والهنود والشعوب الأصلية في صباح (Sabah) وساراواك (Sarawak). من نظام تعليمي متعدد المسارات والرعاية الصحية العامة إلى الحياة الحضرية السريعة النمو — توازن الأمة باستمرار بين التنوع والوحدة. استكشف المجتمع الماليزي وأنظمته الاجتماعية.',
    hi: 'मलेशियाई समाज नस्लों, धर्मों और भाषाओं की एक पच्चीकारी है — मलय, चीनी, भारतीय, और Sabah तथा Sarawak के मूलनिवासी। बहु-धारा शिक्षा प्रणाली और सार्वजनिक स्वास्थ्य सेवा से लेकर तेज़ी से बढ़ते शहरी जीवन तक — राष्ट्र निरंतर विविधता और एकता के बीच संतुलन बनाता है। मलेशिया के समाज और सामाजिक प्रणालियों का अन्वेषण करें।',
    es: 'La sociedad malasia es un mosaico de razas, religiones y lenguas: malaya, china, india y los pueblos indígenas de Sabah y Sarawak. Desde un sistema educativo de múltiples vertientes y la sanidad pública hasta una vida urbana de rápido crecimiento, la nación equilibra constantemente la diversidad con la unidad. Explora la sociedad malasia y sus sistemas sociales.',
    fr: "La société malaisienne est une mosaïque de peuples, de religions et de langues : malais, chinois, indiens et peuples autochtones du Sabah et du Sarawak. D'un système éducatif à filières multiples et de la santé publique à une vie urbaine en pleine expansion, la nation cherche en permanence l'équilibre entre diversité et unité. Explorez la société malaisienne et ses systèmes sociaux.",
  },
  economy: {
    ms: 'Ekonomi Malaysia telah berubah dari pergantungan pada getah dan bijih timah kepada perindustrian, elektronik, dan perkhidmatan. Minyak sawit dan tenaga menyumbang besar, manakala pelancongan dan kewangan berkembang pesat. Terokai komoditi, tenaga, perindustrian, dan perkhidmatan yang menggerakkan negara.',
    en: "Malaysia's economy has shifted from a reliance on rubber and tin to manufacturing, electronics, and services. Palm oil and energy remain major contributors, while tourism and finance grow rapidly. Explore the commodities, energy, industry, and services that drive the nation.",
    zh: '马来西亚经济已从依赖橡胶与锡矿，转向制造业、电子业与服务业。棕油与能源仍是主要贡献，旅游与金融则快速增长。探索驱动国家的大宗商品、能源、工业与服务业。',
    ta: 'மலேசியப் பொருளாதாரம் ரப்பர் மற்றும் தகரத்தை நம்பியிருந்த நிலையிலிருந்து உற்பத்தித் தொழில், மின்னணுவியல் மற்றும் சேவைகளுக்கு மாறியுள்ளது. பாமாயிலும் ஆற்றலும் இன்னும் முக்கிய பங்களிப்பாளர்களாக உள்ளன, சுற்றுலாவும் நிதித்துறையும் விரைவாக வளர்கின்றன. நாட்டை இயக்கும் மூலப்பொருட்கள், ஆற்றல், தொழில் மற்றும் சேவைகளை ஆராயுங்கள்.',
    ja: 'マレーシア経済は、ゴムとスズへの依存から、製造業、電子産業、サービス業へと転換してきました。パーム油とエネルギーは依然として主要な担い手であり、観光と金融は急速に成長しています。国を動かす一次産品、エネルギー、産業、サービスを見てみましょう。',
    ko: '말레이시아 경제는 고무와 주석에 대한 의존에서 제조업, 전자산업, 서비스업으로 전환해 왔습니다. 팜유와 에너지는 여전히 주요한 기여 부문이며, 관광과 금융은 빠르게 성장하고 있습니다. 국가를 이끄는 원자재, 에너지, 산업, 서비스를 탐색해 보십시오.',
    th: 'เศรษฐกิจของมาเลเซียได้เปลี่ยนจากการพึ่งพายางพาราและดีบุก ไปสู่ภาคการผลิต อิเล็กทรอนิกส์ และบริการ น้ำมันปาล์มและพลังงานยังคงเป็นผู้สร้างรายได้หลัก ขณะที่การท่องเที่ยวและการเงินเติบโตอย่างรวดเร็ว สำรวจสินค้าโภคภัณฑ์ พลังงาน อุตสาหกรรม และบริการที่ขับเคลื่อนประเทศ',
    vi: 'Nền kinh tế Malaysia đã chuyển dịch từ sự phụ thuộc vào cao su và thiếc sang chế tạo, điện tử và dịch vụ. Dầu cọ và năng lượng vẫn là những nguồn đóng góp chính, trong khi du lịch và tài chính tăng trưởng nhanh chóng. Khám phá các mặt hàng, năng lượng, công nghiệp và dịch vụ đang vận hành đất nước.',
    id: 'Ekonomi Malaysia telah beralih dari ketergantungan pada karet dan bijih timah ke manufaktur, elektronik, dan jasa. Minyak sawit dan energi tetap menjadi penyumbang besar, sementara pariwisata dan keuangan tumbuh pesat. Jelajahi komoditas, energi, industri, dan jasa yang menggerakkan negara ini.',
    ar: 'تحوّل اقتصاد ماليزيا من الاعتماد على المطاط والقصدير إلى التصنيع والإلكترونيات والخدمات. ولا يزال زيت النخيل والطاقة من أهم المساهمين، في حين تنمو السياحة والتمويل بسرعة. استكشف السلع والطاقة والصناعة والخدمات التي تحرّك الأمة.',
    hi: 'मलेशिया की अर्थव्यवस्था रबर और टिन पर निर्भरता से हटकर विनिर्माण, इलेक्ट्रॉनिक्स और सेवाओं की ओर बढ़ गई है। पाम तेल और ऊर्जा प्रमुख योगदानकर्ता बने हुए हैं, जबकि पर्यटन और वित्त तेज़ी से बढ़ रहे हैं। राष्ट्र को चलाने वाली वस्तुओं, ऊर्जा, उद्योग और सेवाओं का अन्वेषण करें।',
    es: 'La economía de Malasia ha pasado de depender del caucho y el estaño a la manufactura, la electrónica y los servicios. El aceite de palma y la energía siguen siendo grandes contribuyentes, mientras que el turismo y las finanzas crecen con rapidez. Explora las materias primas, la energía, la industria y los servicios que impulsan la nación.',
    fr: "L'économie de la Malaisie est passée de la dépendance au caoutchouc et à l'étain à l'industrie manufacturière, à l'électronique et aux services. L'huile de palme et l'énergie demeurent des contributeurs majeurs, tandis que le tourisme et la finance connaissent une croissance rapide. Explorez les matières premières, l'énergie, l'industrie et les services qui font avancer la nation.",
  },
  technology: {
    ms: 'Malaysia membina masa depan digitalnya di atas asas industri elektronik dan semikonduktor yang berdekad lamanya. Dari Koridor Raya Multimedia dan Cyberjaya ke industri cip Pulau Pinang, program angkasa, dan gelombang syarikat pemula — negara berusaha bergerak menaiki rantaian nilai teknologi. Terokai teknologi Malaysia mengikut bidang.',
    en: "Malaysia is building its digital future on decades of electronics and semiconductor industry. From the Multimedia Super Corridor and Cyberjaya to Penang's chip industry, a space programme, and a wave of startups — the nation is working to move up the technology value chain. Explore Malaysian technology by field.",
    zh: '马来西亚在数十年电子与半导体产业的基础上打造数字未来。从多媒体超级走廊、赛城，到槟城的芯片产业、航天计划与新创浪潮——国家正努力向技术价值链上游迈进。按领域探索马来西亚科技。',
    ta: 'மலேசியா பல்லாண்டுகால மின்னணு மற்றும் அரைக்கடத்தித் தொழிலின் அடித்தளத்தில் தனது டிஜிட்டல் எதிர்காலத்தைக் கட்டியெழுப்புகிறது. மல்டிமீடியா சூப்பர் காரிடார் மற்றும் சைபர்ஜெயா முதல் பினாங்கின் சிப் தொழில், விண்வெளித் திட்டம் மற்றும் தொடக்கநிறுவனங்களின் அலை வரை — நாடு தொழில்நுட்ப மதிப்புச் சங்கிலியில் மேலே ஏற முயற்சிக்கிறது. மலேசியத் தொழில்நுட்பத்தை துறை வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシアは、数十年にわたる電子・半導体産業を基盤に、デジタルの未来を築いています。マルチメディア・スーパー・コリドーやサイバージャヤから、ペナンのチップ産業、宇宙計画、スタートアップの波まで——国は技術のバリューチェーンを上っていこうとしています。マレーシアのテクノロジーを分野別に見てみましょう。',
    ko: '말레이시아는 수십 년에 걸친 전자·반도체 산업을 토대로 디지털 미래를 구축하고 있습니다. 멀티미디어 슈퍼 코리도(Multimedia Super Corridor)와 사이버자야(Cyberjaya)에서 페낭(Penang)의 반도체 산업, 우주 계획, 그리고 스타트업의 물결에 이르기까지 — 국가는 기술 가치사슬의 상위로 올라서고자 힘쓰고 있습니다. 분야별로 말레이시아의 기술을 탐색해 보십시오.',
    th: 'มาเลเซียกำลังสร้างอนาคตดิจิทัลของตนบนรากฐานอุตสาหกรรมอิเล็กทรอนิกส์และเซมิคอนดักเตอร์ที่สั่งสมมาหลายทศวรรษ จากมัลติมีเดียซูเปอร์คอร์ริดอร์ (Multimedia Super Corridor) และไซเบอร์จายา (Cyberjaya) ไปจนถึงอุตสาหกรรมชิปของปีนัง (Penang) โครงการอวกาศ และคลื่นของสตาร์ตอัป — ประเทศกำลังพยายามก้าวขึ้นสู่ห่วงโซ่คุณค่าทางเทคโนโลยีที่สูงขึ้น สำรวจเทคโนโลยีมาเลเซียตามสาขา',
    vi: 'Malaysia đang xây dựng tương lai số của mình trên nền tảng nhiều thập kỷ của ngành công nghiệp điện tử và bán dẫn. Từ Hành lang Đa phương tiện Siêu tốc (Multimedia Super Corridor) và Cyberjaya đến ngành công nghiệp chip của Penang, một chương trình không gian, và làn sóng các công ty khởi nghiệp — đất nước đang nỗ lực vươn lên trong chuỗi giá trị công nghệ. Khám phá công nghệ Malaysia theo từng lĩnh vực.',
    id: 'Malaysia membangun masa depan digitalnya di atas fondasi industri elektronik dan semikonduktor yang telah berlangsung puluhan tahun. Dari Koridor Raya Multimedia dan Cyberjaya hingga industri chip Pulau Pinang, program antariksa, dan gelombang perusahaan rintisan — negara berupaya bergerak naik dalam rantai nilai teknologi. Jelajahi teknologi Malaysia berdasarkan bidang.',
    ar: 'تبني ماليزيا مستقبلها الرقمي على عقود من صناعة الإلكترونيات وأشباه الموصلات. من ممر الوسائط المتعددة الفائق (Multimedia Super Corridor) وسايبرجايا (Cyberjaya) إلى صناعة الرقائق في بينانغ (Penang)، وبرنامج فضائي، وموجة من الشركات الناشئة — تسعى الأمة إلى الارتقاء في سلسلة القيمة التكنولوجية. استكشف التكنولوجيا الماليزية حسب المجال.',
    hi: 'मलेशिया दशकों पुराने इलेक्ट्रॉनिक्स और सेमीकंडक्टर उद्योग की नींव पर अपना डिजिटल भविष्य गढ़ रहा है। Multimedia Super Corridor और Cyberjaya से लेकर Penang के चिप उद्योग, एक अंतरिक्ष कार्यक्रम, और स्टार्टअप्स की लहर तक — राष्ट्र प्रौद्योगिकी मूल्य-शृंखला में ऊपर बढ़ने का प्रयास कर रहा है। क्षेत्र के अनुसार मलेशियाई प्रौद्योगिकी का अन्वेषण करें।',
    es: 'Malasia construye su futuro digital sobre décadas de industria electrónica y de semiconductores. Desde el Multimedia Super Corridor y Cyberjaya hasta la industria de chips de Penang, un programa espacial y una oleada de empresas emergentes, la nación trabaja para ascender en la cadena de valor tecnológica. Explora la tecnología malasia por campo.',
    fr: "La Malaisie bâtit son avenir numérique sur des décennies d'industrie électronique et de semi-conducteurs. Du Multimedia Super Corridor et de Cyberjaya à l'industrie des puces de Penang, en passant par un programme spatial et une vague de start-up, la nation s'efforce de monter dans la chaîne de valeur technologique. Explorez la technologie malaisienne par domaine.",
  },
  languages: {
    ms: 'Malaysia ialah negara berbilang bahasa. Bahasa Malaysia menyatukan rakyat sebagai bahasa kebangsaan, di samping bahasa Inggeris, dialek Cina, Tamil, dan puluhan bahasa peribumi Sabah dan Sarawak. Tulisan Jawi dan Rumi pula mewarnai sejarah penulisannya. Terokai bahasa dan tulisan yang membentuk suara negara.',
    en: "Malaysia is a multilingual nation. Bahasa Malaysia unites the people as the national language, alongside English, Chinese dialects, Tamil, and dozens of indigenous languages of Sabah and Sarawak. The Jawi and Rumi scripts colour its written history. Explore the languages and scripts that form the nation's voice.",
    zh: '马来西亚是一个多语言国家。马来语作为国语凝聚人民，此外还有英语、华语方言、淡米尔语，以及沙巴和砂拉越数十种原住民语言。爪夷文与罗马字则丰富了其书写历史。探索构成国家之声的语言与文字。',
    ta: 'மலேசியா ஒரு பன்மொழி நாடு. மலாய் மொழி தேசிய மொழியாக மக்களை ஒன்றிணைக்கிறது; அதனுடன் ஆங்கிலம், சீன வட்டார மொழிகள், தமிழ், மற்றும் சபா மற்றும் சரவாக்கின் டஜன் கணக்கான பழங்குடி மொழிகளும் உள்ளன. ஜாவி மற்றும் ருமி எழுத்துமுறைகள் அதன் எழுத்து வரலாற்றுக்கு நிறம் சேர்க்கின்றன. நாட்டின் குரலை உருவாக்கும் மொழிகளையும் எழுத்துமுறைகளையும் ஆராயுங்கள்.',
    ja: 'マレーシアは多言語の国です。マレー語は国語として人々を結びつけ、そのほかに英語、華語の方言、タミル語、そしてサバとサラワクの数十の先住民言語があります。ジャウィ文字とルミ（ローマ字）がその文字の歴史に彩りを添えています。国の声を形づくる言語と文字を見てみましょう。',
    ko: '말레이시아는 다언어 국가입니다. 말레이어(Bahasa Malaysia)는 국어로서 국민을 하나로 묶으며, 그 밖에도 영어, 중국어 방언, 타밀어, 그리고 사바(Sabah)와 사라왁(Sarawak)의 수십 개 원주민 언어가 있습니다. 자위(Jawi) 문자와 루미(Rumi) 문자는 그 문자의 역사에 색을 더합니다. 국가의 목소리를 이루는 언어와 문자를 탐색해 보십시오.',
    th: 'มาเลเซียเป็นชาติที่มีหลายภาษา ภาษามลายู (Bahasa Malaysia) เชื่อมผู้คนเข้าด้วยกันในฐานะภาษาประจำชาติ ควบคู่ไปกับภาษาอังกฤษ ภาษาถิ่นจีน ภาษาทมิฬ และภาษาพื้นเมืองหลายสิบภาษาของรัฐซาบาห์ (Sabah) และรัฐซาราวัก (Sarawak) อักษรยาวี (Jawi) และอักษรรูมี (Rumi) เพิ่มสีสันให้แก่ประวัติศาสตร์การเขียนของประเทศ สำรวจภาษาและอักษรที่ประกอบขึ้นเป็นเสียงของชาติ',
    vi: 'Malaysia là một quốc gia đa ngôn ngữ. Tiếng Malaysia (Bahasa Malaysia) gắn kết người dân với tư cách là ngôn ngữ quốc gia, bên cạnh tiếng Anh, các phương ngữ Hoa, tiếng Tamil, và hàng chục ngôn ngữ bản địa của Sabah và Sarawak. Chữ viết Jawi và Rumi tô điểm cho lịch sử chữ viết của đất nước. Khám phá các ngôn ngữ và hệ chữ viết tạo nên tiếng nói của dân tộc.',
    id: 'Malaysia adalah negara multibahasa. Bahasa Malaysia menyatukan rakyat sebagai bahasa nasional, di samping bahasa Inggris, dialek Tionghoa, Tamil, dan puluhan bahasa asli Sabah dan Sarawak. Aksara Jawi dan Rumi mewarnai sejarah penulisannya. Jelajahi bahasa dan aksara yang membentuk suara bangsa.',
    ar: 'ماليزيا أمة متعددة اللغات. توحّد اللغة الماليزية (Bahasa Malaysia) الناس بوصفها اللغة الوطنية، إلى جانب الإنجليزية واللهجات الصينية والتاميلية وعشرات اللغات الأصلية في صباح (Sabah) وساراواك (Sarawak). ويضفي خطّا الجاوي (Jawi) والرومي (Rumi) ألوانًا على تاريخها المكتوب. استكشف اللغات والخطوط التي تشكّل صوت الأمة.',
    hi: 'मलेशिया एक बहुभाषी राष्ट्र है। Bahasa Malaysia राष्ट्रभाषा के रूप में लोगों को एकजुट करती है, साथ ही अंग्रेज़ी, चीनी बोलियाँ, तमिल, और Sabah तथा Sarawak की दर्जनों मूलनिवासी भाषाएँ भी हैं। Jawi और Rumi लिपियाँ इसके लेखन के इतिहास में रंग भरती हैं। राष्ट्र की आवाज़ गढ़ने वाली भाषाओं और लिपियों का अन्वेषण करें।',
    es: 'Malasia es una nación multilingüe. El bahasa Malaysia une a la gente como lengua nacional, junto al inglés, los dialectos chinos, el tamil y decenas de lenguas indígenas de Sabah y Sarawak. Las escrituras jawi y rumi dan color a su historia escrita. Explora las lenguas y escrituras que conforman la voz de la nación.',
    fr: "La Malaisie est une nation multilingue. Le bahasa Malaysia unit le peuple en tant que langue nationale, aux côtés de l'anglais, des dialectes chinois, du tamoul et de dizaines de langues autochtones du Sabah et du Sarawak. Les écritures jawi et rumi colorent son histoire écrite. Explorez les langues et les écritures qui forment la voix de la nation.",
  },
  'art-music': {
    ms: 'Seni Malaysia terbentang dari kraf warisan seperti batik dan ukiran, ke seni persembahan tradisional seperti wayang kulit dan mak yong, muzik dari gamelan ke pop moden, dan sinema dari zaman P. Ramlee ke pembikin filem baharu. Terokai seni dan muzik yang menghidupkan budaya negara.',
    en: "Malaysian art spans heritage crafts like batik and carving, traditional performing arts like wayang kulit and mak yong, music from gamelan to modern pop, and cinema from the P. Ramlee era to new filmmakers. Explore the art and music that bring the nation's culture to life.",
    zh: '马来西亚艺术涵盖蜡染、雕刻等传统工艺，皮影戏、玛蓉舞等传统表演艺术，从甘美兰到现代流行的音乐，以及从 P. Ramlee 时代到新一代影人的电影。探索让国家文化鲜活起来的艺术与音乐。',
    ta: 'மலேசியக் கலை பாத்திக் மற்றும் சிற்பம் போன்ற பாரம்பரியக் கைவினைகள், வயாங் குலித் மற்றும் மாக் யோங் போன்ற பாரம்பரிய நிகழ்த்துக் கலைகள், கமிலான் முதல் நவீன பாப் வரையிலான இசை, மற்றும் P. Ramlee காலம் முதல் புதிய திரைப்பட ஆக்கியோர் வரையிலான சினிமா என விரிந்துள்ளது. நாட்டின் பண்பாட்டை உயிர்ப்பிக்கும் கலையையும் இசையையும் ஆராயுங்கள்.',
    ja: 'マレーシアの芸術は、バティックや彫刻のような伝統工芸、ワヤン・クリ（影絵芝居）やマ・ヨンのような伝統芸能、ガムランから現代のポップまでの音楽、そしてP. Ramleeの時代から新世代の映画作家までの映画にわたります。国の文化を生き生きとさせる芸術と音楽を見てみましょう。',
    ko: '말레이시아 예술은 바틱(batik)과 조각 같은 전통 공예, 와양 쿨릿(wayang kulit)과 막용(mak yong) 같은 전통 공연 예술, 가믈란(gamelan)에서 현대 대중음악에 이르는 음악, 그리고 P. Ramlee 시대부터 새로운 영화인들에 이르는 영화에 걸쳐 있습니다. 국가의 문화를 생생하게 살아나게 하는 예술과 음악을 탐색해 보십시오.',
    th: 'ศิลปะมาเลเซียครอบคลุมตั้งแต่งานหัตถกรรมมรดกอย่างผ้าบาติก (batik) และงานแกะสลัก ศิลปะการแสดงดั้งเดิมอย่างวายังกูลิต (wayang kulit) และมะโย่ง (mak yong) ดนตรีตั้งแต่กาเมลัน (gamelan) ไปจนถึงเพลงป็อปสมัยใหม่ และภาพยนตร์ตั้งแต่ยุค พี. รามลี (P. Ramlee) ไปจนถึงผู้สร้างภาพยนตร์รุ่นใหม่ สำรวจศิลปะและดนตรีที่ทำให้วัฒนธรรมของชาติมีชีวิตชีวา',
    vi: 'Nghệ thuật Malaysia trải rộng từ các nghề thủ công di sản như batik và điêu khắc, các loại hình nghệ thuật biểu diễn truyền thống như wayang kulit và mak yong, âm nhạc từ gamelan đến pop hiện đại, và điện ảnh từ thời P. Ramlee đến những nhà làm phim mới. Khám phá nghệ thuật và âm nhạc mang văn hóa của dân tộc đến với đời sống.',
    id: 'Seni Malaysia terbentang dari kerajinan warisan seperti batik dan ukiran, hingga seni pertunjukan tradisional seperti wayang kulit dan mak yong, musik dari gamelan hingga pop modern, dan sinema dari era P. Ramlee hingga para pembuat film baru. Jelajahi seni dan musik yang menghidupkan budaya bangsa.',
    ar: 'يمتد الفن الماليزي من الحرف التراثية مثل الباتيك (batik) والنحت، إلى فنون الأداء التقليدية مثل وايانغ كوليت (wayang kulit) ومأك يونغ (mak yong)، والموسيقى من الغاملان (gamelan) إلى البوب الحديث، والسينما من حقبة P. Ramlee إلى صنّاع الأفلام الجدد. استكشف الفن والموسيقى اللذين يبعثان ثقافة الأمة إلى الحياة.',
    hi: 'मलेशियाई कला batik और नक्काशी जैसी विरासती शिल्पकलाओं, wayang kulit और mak yong जैसी पारंपरिक प्रदर्शन कलाओं, gamelan से लेकर आधुनिक पॉप तक के संगीत, और P. Ramlee के युग से लेकर नए फ़िल्मकारों तक की सिनेमा में फैली है। राष्ट्र की संस्कृति को जीवंत करने वाली कला और संगीत का अन्वेषण करें।',
    es: 'El arte malasio abarca artesanías patrimoniales como el batik y la talla, artes escénicas tradicionales como el wayang kulit y el mak yong, música desde el gamelan hasta el pop moderno, y cine desde la era de P. Ramlee hasta los nuevos cineastas. Explora el arte y la música que dan vida a la cultura de la nación.',
    fr: "L'art malaisien englobe des artisanats patrimoniaux comme le batik et la sculpture, des arts du spectacle traditionnels comme le wayang kulit et le mak yong, une musique allant du gamelan à la pop moderne, et un cinéma qui va de l'époque de P. Ramlee aux nouveaux cinéastes. Explorez l'art et la musique qui font vivre la culture de la nation.",
  },
  lifestyle: {
    ms: 'Kehidupan harian di Malaysia berlegar di sekitar makanan, pasar, dan perhubungan masyarakat. Dari gerai mamak 24 jam dan kopitiam ke pasar malam yang meriah, dari badminton dan sepak takraw ke kehidupan bandar yang pesat — inilah irama sebenar rakyat Malaysia. Terokai gaya hidup negara mengikut tema.',
    en: "Daily life in Malaysia revolves around food, markets, and community. From 24-hour mamak stalls and kopitiam to bustling night markets, from badminton and sepak takraw to fast-paced urban life — this is the real rhythm of Malaysians. Explore the country's lifestyle by theme.",
    zh: '马来西亚的日常生活围绕着美食、市场与社群。从 24 小时嘛嘛档、咖啡店到热闹的夜市，从羽毛球、藤球到快节奏的城市生活——这正是马来西亚人真实的生活节奏。按主题探索这个国家的生活方式。',
    ta: 'மலேசியாவின் அன்றாட வாழ்க்கை உணவு, சந்தைகள் மற்றும் சமூகத்தைச் சுற்றியே அமைந்துள்ளது. 24 மணிநேர மாமாக் கடைகள் மற்றும் கோபிதியாம் முதல் சுறுசுறுப்பான இரவுச் சந்தைகள் வரை, பூப்பந்து மற்றும் செபாக் தக்ரா முதல் வேகமான நகர வாழ்க்கை வரை — இதுவே மலேசியர்களின் உண்மையான வாழ்வின் தாளம். நாட்டின் வாழ்க்கை முறையை கருப்பொருள் வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシアの日常生活は、食、市場、コミュニティを中心に回っています。24時間営業のママック屋台やコピティアムから賑やかなナイトマーケットまで、バドミントンやセパタクローから慌ただしい都市生活まで——これがマレーシア人の本当の生活のリズムです。国のライフスタイルをテーマ別に見てみましょう。',
    ko: '말레이시아의 일상은 음식과 시장, 그리고 공동체를 중심으로 돌아갑니다. 24시간 운영되는 마막(mamak) 노점과 코피티암(kopitiam)에서 활기찬 야시장까지, 배드민턴과 세팍타크로에서 빠르게 돌아가는 도시 생활까지 — 이것이 말레이시아인의 진정한 삶의 리듬입니다. 주제별로 이 나라의 생활 방식을 탐색해 보십시오.',
    th: 'ชีวิตประจำวันในมาเลเซียหมุนรอบอาหาร ตลาด และชุมชน จากร้านมามัก (mamak) ที่เปิด 24 ชั่วโมงและร้านโกปี้เตี่ยม (kopitiam) ไปจนถึงตลาดกลางคืนที่คึกคัก จากแบดมินตันและตะกร้อ (sepak takraw) ไปจนถึงชีวิตในเมืองที่เร่งรีบ — นี่คือจังหวะชีวิตที่แท้จริงของชาวมาเลเซีย สำรวจวิถีชีวิตของประเทศตามหัวข้อ',
    vi: 'Đời sống thường nhật ở Malaysia xoay quanh ẩm thực, chợ búa và cộng đồng. Từ những quầy mamak mở 24 giờ và kopitiam đến những khu chợ đêm nhộn nhịp, từ cầu lông và sepak takraw đến nhịp sống đô thị hối hả — đây chính là nhịp điệu thực sự của người Malaysia. Khám phá lối sống của đất nước theo chủ đề.',
    id: 'Kehidupan sehari-hari di Malaysia berputar di sekitar makanan, pasar, dan hubungan masyarakat. Dari gerai mamak 24 jam dan kopitiam hingga pasar malam yang meriah, dari bulu tangkis dan sepak takraw hingga kehidupan kota yang pesat — inilah irama sejati rakyat Malaysia. Jelajahi gaya hidup negara ini berdasarkan tema.',
    ar: 'تدور الحياة اليومية في ماليزيا حول الطعام والأسواق والمجتمع. من أكشاك الماماك (mamak) المفتوحة 24 ساعة والكوبيتيام (kopitiam) إلى أسواق الليل الصاخبة، ومن كرة الريشة والسيباك تكراو (sepak takraw) إلى الحياة الحضرية السريعة الإيقاع — هذا هو الإيقاع الحقيقي للماليزيين. استكشف نمط حياة البلد حسب الموضوع.',
    hi: 'मलेशिया में दैनिक जीवन भोजन, बाज़ारों और समुदाय के इर्द-गिर्द घूमता है। 24-घंटे खुलने वाले mamak स्टॉलों और kopitiam से लेकर गुलज़ार रात्रि बाज़ारों तक, बैडमिंटन और sepak takraw से लेकर तेज़-रफ़्तार शहरी जीवन तक — यही मलेशियाई लोगों की असली लय है। विषय के अनुसार देश की जीवनशैली का अन्वेषण करें।',
    es: 'La vida cotidiana en Malasia gira en torno a la comida, los mercados y la comunidad. Desde los puestos mamak abiertos las 24 horas y los kopitiam hasta los bulliciosos mercados nocturnos, desde el bádminton y el sepak takraw hasta la vertiginosa vida urbana, este es el verdadero ritmo de los malasios. Explora el estilo de vida del país por temas.',
    fr: "La vie quotidienne en Malaisie tourne autour de la nourriture, des marchés et de la communauté. Des échoppes mamak ouvertes 24 heures sur 24 et des kopitiam aux marchés de nuit animés, du badminton et du sepak takraw à la vie urbaine trépidante, tel est le véritable rythme des Malaisiens. Explorez le mode de vie du pays par thème.",
  },
  'business-regions': {
    ms: 'Berniaga mengikut wilayah di Malaysia — dari Kuala Lumpur, Selangor, dan Pulau Pinang ke Johor, Sabah, dan Sarawak, serta koridor ekonomi seperti Iskandar Malaysia. Setiap wilayah mempunyai ekosistem, kos, bakat, dan insentif tersendiri. Panduan lokasi untuk usahawan dan pelabur. Nota: maklumat umum, bukan nasihat profesional.',
    en: "Doing business by region in Malaysia — from Kuala Lumpur, Selangor, and Penang to Johor, Sabah, and Sarawak, plus economic corridors like Iskandar Malaysia. Each region has its own ecosystem, costs, talent, and incentives. Location guides for founders and investors. Note: general information, not professional advice.",
    zh: '在马来西亚各地营商——从吉隆坡、雪兰莪、槟城，到柔佛、沙巴与砂拉越，以及依斯干达等经济走廊。每个地区都有其独特的生态、成本、人才与优惠。为创业者与投资者提供的选址指南。注：一般信息，非专业建议。',
    ta: 'மலேசியாவில் வட்டாரம் வாரியாக வணிகம் செய்தல் — கோலாலம்பூர், சிலாங்கூர், பினாங்கு முதல் ஜொகூர், சபா, சரவாக் வரை, அத்துடன் இஸ்கந்தர் மலேசியா போன்ற பொருளாதார வழித்தடங்களும். ஒவ்வொரு பகுதிக்கும் தனக்கே உரிய சூழல்தொகுதி, செலவுகள், திறமையாளர்கள் மற்றும் ஊக்கத்தொகைகள் உண்டு. தொழில்முனைவோருக்கும் முதலீட்டாளர்களுக்கும் இட வழிகாட்டிகள். குறிப்பு: பொதுத் தகவல், தொழில்முறை ஆலோசனை அன்று.',
    ja: 'マレーシアで地域別にビジネスを——クアラルンプール、セランゴール、ペナンから、ジョホール、サバ、サラワク、さらにイスカンダル・マレーシアのような経済回廊まで。各地域には独自のエコシステム、コスト、人材、優遇策があります。起業家と投資家のための立地ガイド。注：一般的な情報であり、専門的な助言ではありません。',
    ko: '말레이시아에서 지역별로 사업하기 — 쿠알라룸푸르(Kuala Lumpur), 슬랑오르(Selangor), 페낭(Penang)에서 조호르(Johor), 사바(Sabah), 사라왁(Sarawak)까지, 그리고 이스칸다르 말레이시아(Iskandar Malaysia) 같은 경제 회랑을 아우릅니다. 각 지역은 저마다의 생태계, 비용, 인재, 인센티브를 갖추고 있습니다. 창업자와 투자자를 위한 입지 안내입니다. 참고: 일반 정보이며, 전문적인 자문이 아닙니다.',
    th: 'การทำธุรกิจตามภูมิภาคในมาเลเซีย — จากกัวลาลัมเปอร์ (Kuala Lumpur) สลังงอร์ (Selangor) และปีนัง (Penang) ไปจนถึงยะโฮร์ (Johor) ซาบาห์ (Sabah) และซาราวัก (Sarawak) รวมถึงระเบียงเศรษฐกิจอย่างอิสกันดาร์มาเลเซีย (Iskandar Malaysia) แต่ละภูมิภาคมีระบบนิเวศ ต้นทุน บุคลากร และสิทธิประโยชน์เป็นของตนเอง คู่มือทำเลสำหรับผู้ก่อตั้งธุรกิจและนักลงทุน หมายเหตุ: เป็นข้อมูลทั่วไป ไม่ใช่คำแนะนำทางวิชาชีพ',
    vi: 'Kinh doanh theo vùng tại Malaysia — từ Kuala Lumpur, Selangor và Penang đến Johor, Sabah và Sarawak, cùng các hành lang kinh tế như Iskandar Malaysia. Mỗi vùng có hệ sinh thái, chi phí, nhân lực và ưu đãi riêng. Hướng dẫn về địa điểm dành cho nhà sáng lập và nhà đầu tư. Lưu ý: thông tin chung, không phải tư vấn chuyên môn.',
    id: 'Berbisnis berdasarkan wilayah di Malaysia — dari Kuala Lumpur, Selangor, dan Pulau Pinang hingga Johor, Sabah, dan Sarawak, serta koridor ekonomi seperti Iskandar Malaysia. Setiap wilayah memiliki ekosistem, biaya, talenta, dan insentif tersendiri. Panduan lokasi untuk wirausahawan dan investor. Catatan: informasi umum, bukan nasihat profesional.',
    ar: 'ممارسة الأعمال حسب المنطقة في ماليزيا — من كوالالمبور (Kuala Lumpur) وسلانغور (Selangor) وبينانغ (Penang) إلى جوهور (Johor) وصباح (Sabah) وساراواك (Sarawak)، إضافةً إلى الممرات الاقتصادية مثل إسكندر ماليزيا (Iskandar Malaysia). لكل منطقة منظومتها وتكاليفها وكفاءاتها وحوافزها الخاصة. أدلة المواقع لمؤسِّسي الأعمال والمستثمرين. ملاحظة: معلومات عامة، وليست استشارة مهنية.',
    hi: 'मलेशिया में क्षेत्र के अनुसार व्यवसाय करना — Kuala Lumpur, Selangor और Penang से लेकर Johor, Sabah और Sarawak तक, साथ ही Iskandar Malaysia जैसे आर्थिक गलियारे। प्रत्येक क्षेत्र का अपना पारितंत्र, लागत, प्रतिभा और प्रोत्साहन हैं। संस्थापकों और निवेशकों के लिए स्थान-मार्गदर्शिकाएँ। नोट: सामान्य जानकारी, पेशेवर सलाह नहीं।',
    es: 'Hacer negocios por región en Malasia: desde Kuala Lumpur, Selangor y Penang hasta Johor, Sabah y Sarawak, además de corredores económicos como Iskandar Malaysia. Cada región tiene su propio ecosistema, costes, talento e incentivos. Guías de ubicación para fundadores e inversores. Nota: información general, no asesoramiento profesional.',
    fr: "Faire des affaires par région en Malaisie : de Kuala Lumpur, Selangor et Penang à Johor, au Sabah et au Sarawak, sans oublier des corridors économiques comme Iskandar Malaysia. Chaque région possède son propre écosystème, ses coûts, ses talents et ses incitations. Des guides d'implantation pour les fondateurs et les investisseurs. Remarque : informations générales, ne constituant pas un conseil professionnel.",
  },
  destinations: {
    ms: 'Destinasi Malaysia — dari hiruk-pikuk Kuala Lumpur dan warisan George Town, ke pantai Langkawi dan Pulau Perhentian, hutan hujan Taman Negara, dan puncak Gunung Kinabalu di Borneo. Panduan tempat, alam, pulau, dan maklumat perjalanan untuk pengembara. Terokai mengikut wilayah.',
    en: "Malaysia's destinations — from the buzz of Kuala Lumpur and the heritage of George Town, to the beaches of Langkawi and the Perhentian Islands, the rainforest of Taman Negara, and the summit of Mount Kinabalu on Borneo. Place, nature, island, and travel-info guides for the traveller. Explore by region.",
    zh: '马来西亚的目的地——从吉隆坡的热闹与乔治市的遗产，到兰卡威的海滩与停泊岛，塔曼尼加拉的雨林，以及婆罗洲京那巴鲁山的峰顶。为旅人准备的地点、自然、岛屿与旅行资讯指南。按地区探索。',
    ta: 'மலேசியாவின் சுற்றுலா இடங்கள் — கோலாலம்பூரின் சுறுசுறுப்பும் ஜோர்ஜ் டவுனின் பாரம்பரியமும் முதல் லங்காவியின் கடற்கரைகள் மற்றும் பெர்ஹென்தியன் தீவுகள், தாமான் நெகாரா மழைக்காடு, மற்றும் போர்னியோவில் கினபாலு மலையின் சிகரம் வரை. பயணிகளுக்கான இடம், இயற்கை, தீவு மற்றும் பயணத் தகவல் வழிகாட்டிகள். வட்டாரம் வாரியாக ஆராயுங்கள்.',
    ja: 'マレーシアの旅先——クアラルンプールの活気やジョージタウンの遺産から、ランカウイやプルフンティアン諸島のビーチ、タマン・ヌガラの熱帯雨林、そしてボルネオのキナバル山の頂まで。旅行者のための場所・自然・島・旅の情報ガイド。地域別に見てみましょう。',
    ko: '말레이시아의 여행지 — 쿠알라룸푸르(Kuala Lumpur)의 활기와 조지타운(George Town)의 유산에서, 랑카위(Langkawi)와 프른티안 제도(Perhentian Islands)의 해변, 타만 네가라(Taman Negara)의 열대우림, 그리고 보르네오(Borneo)의 키나발루산(Mount Kinabalu) 정상까지. 여행자를 위한 장소·자연·섬·여행 정보 안내입니다. 지역별로 탐색해 보십시오.',
    th: 'จุดหมายปลายทางของมาเลเซีย — จากความคึกคักของกัวลาลัมเปอร์ (Kuala Lumpur) และมรดกของจอร์จทาวน์ (George Town) ไปจนถึงชายหาดของลังกาวี (Langkawi) และหมู่เกาะเปอร์เฮินเตียน (Perhentian Islands) ป่าฝนของตามันเนอการา (Taman Negara) และยอดเขากีนาบาลู (Mount Kinabalu) บนเกาะบอร์เนียว (Borneo) คู่มือสถานที่ ธรรมชาติ เกาะ และข้อมูลการเดินทางสำหรับนักเดินทาง สำรวจตามภูมิภาค',
    vi: 'Các điểm đến của Malaysia — từ sự sôi động của Kuala Lumpur và di sản của George Town, đến những bãi biển của Langkawi và quần đảo Perhentian (Perhentian Islands), rừng mưa Taman Negara, và đỉnh núi Kinabalu (Mount Kinabalu) trên đảo Borneo. Hướng dẫn về địa điểm, thiên nhiên, đảo và thông tin du lịch dành cho lữ khách. Khám phá theo vùng.',
    id: 'Destinasi Malaysia — dari hiruk-pikuk Kuala Lumpur dan warisan George Town, hingga pantai Langkawi dan Pulau Perhentian, hutan hujan Taman Negara, dan puncak Gunung Kinabalu di Borneo. Panduan tempat, alam, pulau, dan informasi perjalanan untuk pelancong. Jelajahi berdasarkan wilayah.',
    ar: 'وجهات ماليزيا — من صخب كوالالمبور (Kuala Lumpur) وتراث جورج تاون (George Town)، إلى شواطئ لنكاوي (Langkawi) وجزر بيرهينتيان (Perhentian Islands)، والغابة المطيرة في تامان نيغارا (Taman Negara)، وقمة جبل كينابالو (Mount Kinabalu) في بورنيو (Borneo). أدلة الأماكن والطبيعة والجزر ومعلومات السفر للمسافر. استكشف حسب المنطقة.',
    hi: 'मलेशिया के गंतव्य — Kuala Lumpur की चहल-पहल और George Town की विरासत से लेकर Langkawi के समुद्रतटों और Perhentian Islands, Taman Negara के वर्षावन, और बोर्नियो (Borneo) पर माउंट किनाबालु (Mount Kinabalu) के शिखर तक। यात्री के लिए स्थान, प्रकृति, द्वीप और यात्रा-जानकारी की मार्गदर्शिकाएँ। क्षेत्र के अनुसार अन्वेषण करें।',
    es: 'Los destinos de Malasia: desde el bullicio de Kuala Lumpur y el patrimonio de George Town hasta las playas de Langkawi y las islas Perhentian (Perhentian Islands), la selva tropical de Taman Negara y la cima del monte Kinabalu (Mount Kinabalu) en Borneo (Borneo). Guías de lugares, naturaleza, islas e información de viaje para el viajero. Explora por región.',
    fr: "Les destinations de la Malaisie : de l'effervescence de Kuala Lumpur et du patrimoine de George Town aux plages de Langkawi et des îles Perhentian, à la forêt tropicale de Taman Negara et au sommet du mont Kinabalu à Bornéo. Des guides de lieux, de nature, d'îles et d'informations pratiques pour le voyageur. Explorez par région.",
  },
  'business-industries': {
    ms: 'Industri dan sektor Malaysia — dari pembuatan E&E dan semikonduktor, sawit dan komoditi, minyak dan gas, ke perkhidmatan kewangan, ekonomi digital, hartanah, pelancongan, dan perdagangan antarabangsa. Panduan sektor untuk pelabur, usahawan, dan penganalisis. Nota: maklumat umum, bukan nasihat pelaburan.',
    en: "Malaysia's industries and sectors — from E&E and semiconductor manufacturing, palm oil and commodities, oil and gas, to financial services, the digital economy, real estate, tourism, and international trade. Sector guides for investors, founders, and analysts. Note: general information, not investment advice.",
    zh: '马来西亚的行业与领域——从电子电气与半导体制造、棕油与商品、油气，到金融服务、数字经济、房地产、旅游与国际贸易。为投资者、创业者与分析师提供的行业指南。注：一般信息，非投资建议。',
    ta: 'மலேசியாவின் தொழில்களும் துறைகளும் — E&E மற்றும் அரைக்கடத்தி உற்பத்தி, பாமாயில் மற்றும் மூலப்பொருட்கள், எண்ணெய் மற்றும் எரிவாயு முதல் நிதிச் சேவைகள், டிஜிட்டல் பொருளாதாரம், அசையா சொத்து, சுற்றுலா மற்றும் சர்வதேச வர்த்தகம் வரை. முதலீட்டாளர்கள், தொழில்முனைவோர் மற்றும் ஆய்வாளர்களுக்கான துறை வழிகாட்டிகள். குறிப்பு: பொதுத் தகவல், முதலீட்டு ஆலோசனை அன்று.',
    ja: 'マレーシアの産業と分野——E&Eと半導体製造、パーム油と一次産品、石油・ガスから、金融サービス、デジタル経済、不動産、観光、国際貿易まで。投資家、起業家、アナリストのための業界ガイド。注：一般的な情報であり、投資助言ではありません。',
    ko: '말레이시아의 산업과 부문 — 전기·전자(E&E)와 반도체 제조, 팜유와 원자재, 석유·가스에서 금융 서비스, 디지털 경제, 부동산, 관광, 국제 무역까지. 투자자, 창업자, 분석가를 위한 부문 안내입니다. 참고: 일반 정보이며, 투자 자문이 아닙니다.',
    th: 'อุตสาหกรรมและภาคส่วนของมาเลเซีย — จากการผลิต E&E และเซมิคอนดักเตอร์ น้ำมันปาล์มและสินค้าโภคภัณฑ์ น้ำมันและก๊าซ ไปจนถึงบริการทางการเงิน เศรษฐกิจดิจิทัล อสังหาริมทรัพย์ การท่องเที่ยว และการค้าระหว่างประเทศ คู่มือภาคส่วนสำหรับนักลงทุน ผู้ก่อตั้งธุรกิจ และนักวิเคราะห์ หมายเหตุ: เป็นข้อมูลทั่วไป ไม่ใช่คำแนะนำการลงทุน',
    vi: 'Các ngành và lĩnh vực của Malaysia — từ chế tạo E&E và bán dẫn, dầu cọ và hàng hóa, dầu khí, đến dịch vụ tài chính, kinh tế số, bất động sản, du lịch và thương mại quốc tế. Hướng dẫn theo lĩnh vực dành cho nhà đầu tư, nhà sáng lập và nhà phân tích. Lưu ý: thông tin chung, không phải tư vấn đầu tư.',
    id: 'Industri dan sektor Malaysia — dari manufaktur E&E dan semikonduktor, sawit dan komoditas, minyak dan gas, hingga jasa keuangan, ekonomi digital, properti, pariwisata, dan perdagangan internasional. Panduan sektor untuk investor, wirausahawan, dan analis. Catatan: informasi umum, bukan nasihat investasi.',
    ar: 'صناعات ماليزيا وقطاعاتها — من تصنيع الكهربائيات والإلكترونيات (E&E) وأشباه الموصلات، وزيت النخيل والسلع، والنفط والغاز، إلى الخدمات المالية، والاقتصاد الرقمي، والعقارات، والسياحة، والتجارة الدولية. أدلة قطاعية للمستثمرين ومؤسِّسي الأعمال والمحللين. ملاحظة: معلومات عامة، وليست استشارة استثمارية.',
    hi: 'मलेशिया के उद्योग और क्षेत्र — E&E और सेमीकंडक्टर विनिर्माण, पाम तेल और वस्तुएँ, तेल एवं गैस से लेकर वित्तीय सेवाएँ, डिजिटल अर्थव्यवस्था, रियल एस्टेट, पर्यटन और अंतरराष्ट्रीय व्यापार तक। निवेशकों, संस्थापकों और विश्लेषकों के लिए क्षेत्र-मार्गदर्शिकाएँ। नोट: सामान्य जानकारी, निवेश सलाह नहीं।',
    es: 'Las industrias y sectores de Malasia: desde la fabricación de E&E y semiconductores, el aceite de palma y las materias primas, el petróleo y el gas, hasta los servicios financieros, la economía digital, el sector inmobiliario, el turismo y el comercio internacional. Guías sectoriales para inversores, fundadores y analistas. Nota: información general, no asesoramiento de inversión.',
    fr: "Les industries et secteurs de la Malaisie : de la fabrication E&E et de semi-conducteurs, de l'huile de palme et des matières premières, du pétrole et du gaz, aux services financiers, à l'économie numérique, à l'immobilier, au tourisme et au commerce international. Des guides sectoriels pour les investisseurs, les fondateurs et les analystes. Remarque : informations générales, ne constituant pas un conseil en investissement.",
  },
  'business-tax': {
    ms: 'Cukai dan pematuhan di Malaysia — cukai korporat dan peribadi, SST, cukai pegangan, insentif cukai, RPGT, harga pindahan, e-invois, pengauditan, dan regulasi khusus sektor. Panduan praktikal untuk memenuhi kewajipan LHDN dan Kastam. Nota: maklumat umum, bukan nasihat cukai profesional.',
    en: "Tax and compliance in Malaysia — corporate and personal tax, SST, withholding tax, tax incentives, RPGT, transfer pricing, e-invoicing, audit, and sector-specific regulation. A practical guide to meeting LHDN and Customs obligations. Note: general information, not professional tax advice.",
    zh: '马来西亚的税务与合规——企业与个人所得税、销售服务税、预扣税、税务优惠、产业盈利税、转让定价、电子发票、审计与行业监管。满足内陆税收局与关税局义务的实用指南。注：一般信息，非专业税务建议。',
    ta: 'மலேசியாவில் வரியும் இணக்கமும் — நிறுவன மற்றும் தனிநபர் வரி, SST, தடுப்பு வரி, வரி ஊக்கத்தொகைகள், RPGT, இடமாற்று விலை நிர்ணயம், மின்-விலைப்பட்டியல், தணிக்கை மற்றும் துறைசார் ஒழுங்குமுறை. LHDN மற்றும் சுங்கத் துறையின் கடமைகளை நிறைவேற்றுவதற்கான நடைமுறை வழிகாட்டி. குறிப்பு: பொதுத் தகவல், தொழில்முறை வரி ஆலோசனை அன்று.',
    ja: 'マレーシアの税務とコンプライアンス——法人税と個人所得税、SST、源泉徴収税、税制優遇、RPGT（不動産譲渡益税）、移転価格、電子インボイス、監査、業界別規制。LHDN（内国歳入庁）と税関の義務を果たすための実務ガイド。注：一般的な情報であり、専門的な税務助言ではありません。',
    ko: '말레이시아의 세무와 규정 준수 — 법인세와 개인 소득세, 판매·서비스세(SST), 원천징수세, 세제 혜택, 부동산 양도소득세(RPGT), 이전가격, 전자 송장, 감사, 그리고 부문별 규제입니다. 말레이시아 국세청(LHDN)과 관세청의 의무를 이행하기 위한 실무 안내입니다. 참고: 일반 정보이며, 전문적인 세무 자문이 아닙니다.',
    th: 'ภาษีและการปฏิบัติตามข้อกำหนดในมาเลเซีย — ภาษีนิติบุคคลและภาษีบุคคลธรรมดา ภาษีขายและบริการ (SST) ภาษีหัก ณ ที่จ่าย สิทธิประโยชน์ทางภาษี ภาษีกำไรจากการขายอสังหาริมทรัพย์ (RPGT) การกำหนดราคาโอน ใบแจ้งหนี้อิเล็กทรอนิกส์ การตรวจสอบบัญชี และกฎระเบียบเฉพาะภาคส่วน คู่มือเชิงปฏิบัติเพื่อปฏิบัติตามภาระผูกพันต่อกรมสรรพากรมาเลเซีย (LHDN) และกรมศุลกากร หมายเหตุ: เป็นข้อมูลทั่วไป ไม่ใช่คำแนะนำทางภาษีจากผู้เชี่ยวชาญ',
    vi: 'Thuế và tuân thủ tại Malaysia — thuế doanh nghiệp và thuế cá nhân, SST, thuế khấu trừ tại nguồn, ưu đãi thuế, RPGT, xác định giá chuyển nhượng, hóa đơn điện tử, kiểm toán, và quy định riêng theo lĩnh vực. Hướng dẫn thực tiễn để thực hiện các nghĩa vụ với Cục Thuế Nội địa (Inland Revenue Board, LHDN) và Hải quan. Lưu ý: thông tin chung, không phải tư vấn thuế chuyên môn.',
    id: 'Pajak dan kepatuhan di Malaysia — pajak korporat dan pribadi, SST, pajak pemotongan, insentif pajak, RPGT, penetapan harga transfer, e-invois, audit, dan regulasi khusus sektor. Panduan praktis untuk memenuhi kewajiban LHDN dan Kastam. Catatan: informasi umum, bukan nasihat pajak profesional.',
    ar: 'الضرائب والامتثال في ماليزيا — ضريبة الشركات والضريبة الشخصية، وSST، وضريبة الاستقطاع، والحوافز الضريبية، وRPGT، وتسعير التحويل، والفوترة الإلكترونية، والتدقيق، والتنظيم الخاص بكل قطاع. دليل عملي للوفاء بالتزامات الهيئة الماليزية للإيرادات الداخلية (LHDN) والجمارك. ملاحظة: معلومات عامة، وليست استشارة ضريبية مهنية.',
    hi: 'मलेशिया में कर और अनुपालन — कॉर्पोरेट और व्यक्तिगत कर, SST, रोक-कर, कर प्रोत्साहन, RPGT, अंतरण मूल्य-निर्धारण (transfer pricing), ई-चालान, लेखापरीक्षा, और क्षेत्र-विशिष्ट विनियमन। LHDN और Customs के दायित्वों को पूरा करने के लिए एक व्यावहारिक मार्गदर्शिका। नोट: सामान्य जानकारी, पेशेवर कर सलाह नहीं।',
    es: 'Impuestos y cumplimiento en Malasia: impuesto de sociedades y sobre la renta personal, SST, retención en la fuente, incentivos fiscales, RPGT, precios de transferencia, facturación electrónica, auditoría y regulación específica por sector. Una guía práctica para cumplir con las obligaciones ante la LHDN y Aduanas (Customs). Nota: información general, no asesoramiento fiscal profesional.',
    fr: "Fiscalité et conformité en Malaisie : impôt sur les sociétés et impôt sur le revenu des personnes physiques, SST, retenue à la source, incitations fiscales, RPGT, prix de transfert, facturation électronique, audit et réglementation propre à chaque secteur. Un guide pratique pour satisfaire aux obligations envers la LHDN et les douanes (Customs). Remarque : informations générales, ne constituant pas un conseil fiscal professionnel.",
  },
  'business-start': {
    ms: 'Menubuhkan perniagaan di Malaysia — dari memilih struktur Sdn Bhd atau LLP, mendaftar dengan SSM, memenuhi keperluan pengarah dan pemegang saham, hingga pematuhan setiausaha syarikat, HR, perbankan, dan penutupan. Panduan praktikal untuk usahawan tempatan dan asing. Nota: maklumat umum, bukan nasihat profesional.',
    en: "Setting up a business in Malaysia — from choosing a Sdn Bhd or LLP structure, registering with SSM, meeting director and shareholder requirements, through company-secretarial compliance, HR, banking, and closure. A practical guide for local and foreign founders. Note: general information, not professional advice.",
    zh: '在马来西亚创业——从选择私人有限公司或有限责任合伙的架构、向 SSM 注册、满足董事与股东要求，到公司秘书合规、人力资源、银行与关闭。为本地与外国创业者提供的实用指南。注：一般信息，非专业建议。',
    ta: 'மலேசியாவில் வணிகம் தொடங்குதல் — Sdn Bhd அல்லது LLP அமைப்பைத் தேர்ந்தெடுப்பது, SSM-இல் பதிவு செய்வது, இயக்குநர் மற்றும் பங்குதாரர் தேவைகளை நிறைவேற்றுவது முதல், நிறுவனச் செயலாளர் இணக்கம், மனிதவள மேலாண்மை, வங்கிச் சேவை மற்றும் மூடல் வரை. உள்நாட்டு மற்றும் வெளிநாட்டுத் தொழில்முனைவோருக்கான நடைமுறை வழிகாட்டி. குறிப்பு: பொதுத் தகவல், தொழில்முறை ஆலோசனை அன்று.',
    ja: 'マレーシアでの会社設立——Sdn BhdまたはLLPの形態選び、SSMへの登録、取締役・株主要件の充足から、会社秘書役コンプライアンス、人事、銀行取引、清算まで。国内外の起業家のための実務ガイド。注：一般的な情報であり、専門的な助言ではありません。',
    ko: '말레이시아에서 사업 설립하기 — Sdn Bhd 또는 LLP 형태를 선택하고, 말레이시아 기업위원회(SSM)에 등록하며, 이사와 주주 요건을 충족하는 것에서부터 회사 비서 업무 준수, 인사, 은행 업무, 그리고 청산에 이르기까지. 내국인 및 외국인 창업자를 위한 실무 안내입니다. 참고: 일반 정보이며, 전문적인 자문이 아닙니다.',
    th: 'การจัดตั้งธุรกิจในมาเลเซีย — ตั้งแต่การเลือกโครงสร้างแบบ Sdn Bhd หรือ LLP การจดทะเบียนกับ SSM การปฏิบัติตามข้อกำหนดเรื่องกรรมการและผู้ถือหุ้น ไปจนถึงการปฏิบัติตามข้อกำหนดด้านเลขานุการบริษัท การบริหารทรัพยากรบุคคล การธนาคาร และการปิดกิจการ คู่มือเชิงปฏิบัติสำหรับผู้ก่อตั้งธุรกิจทั้งในประเทศและต่างประเทศ หมายเหตุ: เป็นข้อมูลทั่วไป ไม่ใช่คำแนะนำทางวิชาชีพ',
    vi: 'Thành lập doanh nghiệp tại Malaysia — từ việc chọn cơ cấu Sdn Bhd hoặc LLP, đăng ký với Ủy ban Công ty Malaysia (SSM), đáp ứng các yêu cầu về giám đốc và cổ đông, cho đến việc tuân thủ công tác thư ký công ty, nhân sự, ngân hàng và giải thể. Hướng dẫn thực tiễn dành cho nhà sáng lập trong và ngoài nước. Lưu ý: thông tin chung, không phải tư vấn chuyên môn.',
    id: 'Mendirikan bisnis di Malaysia — dari memilih struktur Sdn Bhd atau LLP, mendaftar ke SSM, memenuhi persyaratan direktur dan pemegang saham, hingga kepatuhan sekretaris perusahaan, SDM, perbankan, dan penutupan. Panduan praktis untuk wirausahawan lokal dan asing. Catatan: informasi umum, bukan nasihat profesional.',
    ar: 'تأسيس عمل تجاري في ماليزيا — من اختيار هيكل Sdn Bhd أو LLP، والتسجيل لدى لجنة الشركات الماليزية (SSM)، واستيفاء متطلبات المديرين والمساهمين، إلى الامتثال في أمانة سر الشركة، والموارد البشرية، والأعمال المصرفية، والإغلاق. دليل عملي للمؤسِّسين المحليين والأجانب. ملاحظة: معلومات عامة، وليست استشارة مهنية.',
    hi: 'मलेशिया में व्यवसाय स्थापित करना — Sdn Bhd या LLP संरचना चुनने, SSM के साथ पंजीकरण करने, निदेशक और शेयरधारक आवश्यकताओं को पूरा करने से लेकर कंपनी-सचिवीय अनुपालन, HR, बैंकिंग और समापन तक। स्थानीय और विदेशी संस्थापकों के लिए एक व्यावहारिक मार्गदर्शिका। नोट: सामान्य जानकारी, पेशेवर सलाह नहीं।',
    es: 'Crear una empresa en Malasia: desde elegir una estructura Sdn Bhd o LLP, registrarse en la SSM y cumplir los requisitos de administradores y accionistas, hasta el cumplimiento de la secretaría de la empresa, los recursos humanos, la banca y el cierre. Una guía práctica para fundadores locales y extranjeros. Nota: información general, no asesoramiento profesional.',
    fr: "Créer une entreprise en Malaisie : du choix d'une structure Sdn Bhd ou LLP à l'immatriculation auprès de la SSM et au respect des exigences relatives aux administrateurs et aux actionnaires, jusqu'à la conformité du secrétariat juridique, aux ressources humaines, aux services bancaires et à la clôture. Un guide pratique pour les fondateurs locaux et étrangers. Remarque : informations générales, ne constituant pas un conseil professionnel.",
  },
  politics: {
    ms: 'Malaysia mengamalkan demokrasi berparlimen dan raja berperlembagaan yang unik, dengan Yang di-Pertuan Agong dipilih bergilir dari kalangan sembilan Sultan. Sistem persekutuannya mengimbangi kuasa antara kerajaan pusat dan negeri, digerakkan oleh parti, pilihan raya, dan dasar awam. Terokai politik dan pemerintahan Malaysia.',
    en: "Malaysia practises a unique parliamentary democracy and constitutional monarchy, with the Yang di-Pertuan Agong rotating among nine Sultans. Its federal system balances power between the central and state governments, driven by parties, elections, and public policy. Explore Malaysia's politics and governance.",
    zh: '马来西亚实行独特的议会民主与君主立宪制，最高元首在九位苏丹之间轮任。其联邦制在中央与州政府之间平衡权力，由政党、选举与公共政策推动。探索马来西亚的政治与治理。',
    ta: 'மலேசியா ஒரு தனித்துவமான நாடாளுமன்ற ஜனநாயகத்தையும் அரசியலமைப்பு முடியாட்சியையும் கடைப்பிடிக்கிறது; யாங் டி-பெர்துவான் அகோங் ஒன்பது சுல்தான்களிடையே சுழற்சி முறையில் தேர்ந்தெடுக்கப்படுகிறார். அதன் கூட்டாட்சி முறை மத்திய மற்றும் மாநில அரசுகளுக்கு இடையே அதிகாரத்தைச் சமன் செய்கிறது; கட்சிகள், தேர்தல்கள் மற்றும் பொதுக் கொள்கையால் இயக்கப்படுகிறது. மலேசியாவின் அரசியலையும் ஆட்சியையும் ஆராயுங்கள்.',
    ja: 'マレーシアは独特の議会制民主主義と立憲君主制を採っており、国王（ヤン・ディプルトゥアン・アゴン）は9人のスルタンの間で輪番で選ばれます。連邦制は中央政府と州政府の間で権力の均衡をとり、政党、選挙、公共政策によって動かされています。マレーシアの政治と統治を見てみましょう。',
    ko: '말레이시아는 독특한 의회 민주주의와 입헌군주제를 시행하며, 양 디페르투안 아공(Yang di-Pertuan Agong, 국왕)이 아홉 명의 술탄(Sultan) 사이에서 번갈아 선출됩니다. 그 연방제는 중앙정부와 주정부 사이에서 권력의 균형을 잡으며, 정당, 선거, 공공 정책에 의해 움직입니다. 말레이시아의 정치와 통치를 탐색해 보십시오.',
    th: 'มาเลเซียใช้ระบอบประชาธิปไตยแบบรัฐสภาและระบอบราชาธิปไตยภายใต้รัฐธรรมนูญอันเป็นเอกลักษณ์ โดยมียังดีเปอร์ตวนอากง (Yang di-Pertuan Agong) ผลัดเปลี่ยนหมุนเวียนกันในหมู่สุลต่านเก้าพระองค์ ระบบสหพันธรัฐของประเทศรักษาสมดุลอำนาจระหว่างรัฐบาลกลางและรัฐบาลของรัฐต่าง ๆ ขับเคลื่อนด้วยพรรคการเมือง การเลือกตั้ง และนโยบายสาธารณะ สำรวจการเมืองและการปกครองของมาเลเซีย',
    vi: 'Malaysia thực hành một nền dân chủ nghị viện và quân chủ lập hiến độc đáo, với ngôi vị Yang di-Pertuan Agong luân phiên giữa chín vị Sultan. Hệ thống liên bang của đất nước cân bằng quyền lực giữa chính quyền trung ương và các bang, được vận hành bởi các đảng phái, các cuộc bầu cử và chính sách công. Khám phá nền chính trị và quản trị của Malaysia.',
    id: 'Malaysia menjalankan demokrasi parlementer dan monarki konstitusional yang unik, dengan Yang di-Pertuan Agong yang dipilih secara bergilir dari kalangan sembilan Sultan. Sistem federasinya menyeimbangkan kekuasaan antara pemerintah pusat dan negara bagian, digerakkan oleh partai, pemilihan umum, dan kebijakan publik. Jelajahi politik dan pemerintahan Malaysia.',
    ar: 'تمارس ماليزيا ديمقراطية برلمانية وملكية دستورية فريدة، إذ يتناوب منصب يانغ دي بيرتوان أغونغ (Yang di-Pertuan Agong) بين تسعة سلاطين. ويوازن نظامها الاتحادي السلطة بين الحكومة المركزية وحكومات الولايات، مدفوعًا بالأحزاب والانتخابات والسياسة العامة. استكشف سياسة ماليزيا وحوكمتها.',
    hi: 'मलेशिया एक अनूठे संसदीय लोकतंत्र और संवैधानिक राजतंत्र का पालन करता है, जहाँ Yang di-Pertuan Agong का पद नौ सुल्तानों के बीच बारी-बारी से घूमता है। इसकी संघीय प्रणाली केंद्र और राज्य सरकारों के बीच शक्ति का संतुलन बनाती है, जो दलों, चुनावों और सार्वजनिक नीति से संचालित होती है। मलेशिया की राजनीति और शासन का अन्वेषण करें।',
    es: 'Malasia practica una singular democracia parlamentaria y monarquía constitucional, en la que el Yang di-Pertuan Agong rota entre nueve sultanes. Su sistema federal equilibra el poder entre el gobierno central y los estatales, impulsado por los partidos, las elecciones y las políticas públicas. Explora la política y la gobernanza de Malasia.',
    fr: "La Malaisie pratique une démocratie parlementaire et une monarchie constitutionnelle singulières, dans lesquelles le Yang di-Pertuan Agong est choisi à tour de rôle parmi neuf sultans. Son système fédéral équilibre le pouvoir entre le gouvernement central et les gouvernements des États, sous l'impulsion des partis, des élections et des politiques publiques. Explorez la politique et la gouvernance de la Malaisie.",
  },
};

export function getCategoryIntro(id: string, locale: Locale): string | undefined {
  return CATEGORY_INTRO[id]?.[locale as ContentLocale] ?? CATEGORY_INTRO[id]?.ms;
}
